/* Term 03 additional vocabulary — semantic batch 11. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "تبدیل کردن":["چیزی یا کسی را از یک حالت، شکل یا نوع به حالت یا شکل دیگری درآوردن.","To convert or transform something or someone from one state, form, or type into another.","حوّلَ شيئاً أو شخصاً من حالة أو شكل أو نوع إلى آخر."],
 "تیتر اصلی":["عنوان مهم و برجستهٔ یک خبر یا مقاله که موضوع محوری آن را بیان می‌کند.","The main headline; the prominent title that expresses the central subject of a news story or article.","العنوان الرئيسي؛ العنوان البارز الذي يعبّر عن الموضوع الأساسي لخبر أو مقال."],
 "خبرگزاری":["سازمانی که خبرها را گردآوری، تهیه و برای رسانه‌ها یا مخاطبان منتشر می‌کند.","A news agency; an organisation that gathers and produces news and distributes it to media outlets or the public.","وكالة أنباء؛ مؤسسة تجمع الأخبار وتعدّها وتنشرها لوسائل الإعلام أو للجمهور."],
 "پایگاه خبری":["رسانه یا وب‌سایتی که خبرها و گزارش‌های روز را منتشر می‌کند.","A news outlet or news website that publishes current reports and stories.","منصّة إخبارية أو موقع ينشر الأخبار والتقارير اليومية."],
 "مخاطب":["شخصی که پیام، سخن، نوشته یا برنامه‌ای برای او فرستاده یا ارائه می‌شود.","An audience member, recipient, or addressee; a person to whom a message or programme is directed.","مخاطَب أو متلقٍّ؛ الشخص الذي تُوجَّه إليه رسالة أو كلمة أو مادة إعلامية."],
 "پرمخاطب":["دارای تعداد زیادی مخاطب یا بیننده و شنونده.","Widely followed or having a large audience.","واسع الجمهور؛ له عدد كبير من المتلقّين أو المشاهدين أو المستمعين."],
 "پربیننده":["برنامه، فیلم یا محتوایی که افراد زیادی آن را تماشا می‌کنند.","Highly viewed or popular among viewers; watched by many people.","كثير المشاهدة؛ برنامج أو فيلم أو محتوى يتابعه عدد كبير من الناس."],
 "تبلیغات":["پیام‌ها و فعالیت‌هایی برای معرفی کالا، خدمات، اندیشه یا رویداد و ترغیب مردم به توجه یا خرید آن‌ها.","Advertising or publicity; messages and activities intended to promote a product, service, idea, or event.","الإعلانات أو الدعاية؛ رسائل وأنشطة تهدف إلى التعريف بسلعة أو خدمة أو فكرة أو مناسبة وتشجيع الناس عليها."],
 "قابل اعتماد":["شایستهٔ اعتماد؛ کسی یا چیزی که می‌توان به درستی، صداقت یا عملکرد آن اطمینان کرد.","Trustworthy or reliable; deserving confidence in one's honesty, accuracy, or performance.","جدير بالثقة؛ شخص أو شيء يمكن الاطمئنان إلى صدقه أو دقته أو أدائه."],
 "آواره":["کسی که به سبب جنگ، خطر یا شرایط دشوار ناچار شده خانه و محل زندگی خود را ترک کند.","Displaced or homeless; someone forced to leave their home because of war, danger, or hardship.","نازح أو مشرّد؛ شخص اضطرّ إلى ترك منزله ومكان إقامته بسبب الحرب أو الخطر أو الظروف الصعبة."],
 "جزءبه‌جزء":["به صورت بخش‌بخش و با بررسی یا بیان هر جزء به طور جداگانه.","Part by part; examining or describing each individual component separately.","جزءاً جزءاً؛ مع تناول كل جزء أو شرحه على حدة."],
 "ناراحت‌کننده":["چیزی که موجب اندوه، رنجش یا احساس ناخوشایند در فرد می‌شود.","Upsetting or distressing; causing sadness, hurt, or an unpleasant feeling.","مزعج أو محزن؛ يسبّب الحزن أو الأذى النفسي أو شعوراً غير مريح."],
 "به‌روز":["هماهنگ با تازه‌ترین اطلاعات، تغییرات یا نسخه‌های موجود.","Up-to-date or current; reflecting the latest available information, changes, or version.","مواكب لأحدث المعلومات أو التغييرات أو الإصدارات المتاحة."],
 "راه‌اندازی کردن":["وسیله، دستگاه، سامانه یا فعالیتی را آماده و فعال کردن تا شروع به کار کند.","To set up, launch, or start a device, system, or activity so that it begins operating.","شغّلَ أو أطلقَ جهازاً أو نظاماً أو نشاطاً وجهّزه ليبدأ العمل."],
 "در اختیار قرار دادن":["چیزی را برای استفاده یا بهره‌برداری به شخص یا گروهی سپردن یا فراهم کردن.","To make something available or provide it for someone to use.","وضعَ شيئاً في متناول شخص أو جماعة أو أتاحه لهم للاستعمال."],
 "از مرز گذشتن":["از خط مرزی میان دو کشور یا منطقه عبور کردن؛ همچنین به طور مجازی از حدی فراتر رفتن.","To cross a border between countries or regions; figuratively, to go beyond a limit.","اجتازَ الحدود الفاصلة بين بلدين أو منطقتين؛ ويُستعمل مجازاً لتجاوز حدّ معيّن."],
 "انتخابی عمل کردن":["با توجه به معیارها و نیازها، برخی گزینه‌ها را برگزیدن و از گزینه‌های دیگر صرف‌نظر کردن.","To act selectively by choosing certain options according to criteria or needs and leaving out others.","تصرّفَ بصورة انتقائية، فاختار بعض الخيارات وفق معايير أو حاجات وترك غيرها."],
 "حلوا":["نوعی شیرینی سنتی که معمولاً از آرد، روغن یا کره و شکر یا شیره تهیه می‌شود.","Halva; a traditional sweet commonly made from flour, oil or butter, and sugar or syrup.","حلوى تقليدية تُحضّر عادةً من الدقيق والزيت أو الزبدة والسكر أو القطر."],
 "مراسم سوم":["مراسم یادبود در سومین روز پس از درگذشت فرد که خانواده و آشنایان برای گرامی‌داشت او برگزار می‌کنند.","A third-day memorial gathering held three days after a person's death to honour and remember them.","مراسم تأبين تُقام في اليوم الثالث بعد وفاة شخص لإحياء ذكراه وتكريمه."],
 "هفتم و چهلم":["مراسم یادبود هفتمین و چهلمین روز پس از درگذشت فرد در برخی سنت‌های ایرانی و اسلامی.","The seventh- and fortieth-day memorial observances held after a person's death in some Iranian and Muslim traditions.","مراسم إحياء الذكرى في اليومين السابع والأربعين بعد الوفاة في بعض التقاليد الإيرانية والإسلامية."],
 "سالگرد":["روز یا زمانی که هر سال برای یادآوری یک رویداد مهم، مانند تولد، ازدواج یا درگذشت، فرا می‌رسد.","An anniversary; the yearly return of the date of an important event such as a birth, marriage, or death.","ذكرى سنوية؛ موعد يتكرّر كل عام لإحياء حدث مهم كالولادة أو الزواج أو الوفاة."],
 "زیورآلات":["اشیای تزئینی مانند گردنبند، دستبند، گوشواره و انگشتر که برای آراستن بدن استفاده می‌شوند.","Jewellery or ornaments such as necklaces, bracelets, earrings, and rings worn to decorate the body.","حُليّ وزينة مثل القلائد والأساور والأقراط والخواتم تُلبس لتزيين الجسم."],
 "مناسبت":["رویداد، موقعیت یا زمان ویژه‌ای که به دلیل خاصی مورد توجه یا بزرگداشت قرار می‌گیرد.","An occasion; a particular event, situation, or date marked or observed for a reason.","مناسبة؛ حدث أو ظرف أو موعد خاص يُهتمّ به أو يُحتفى به لسبب معيّن."],
 "فیبر":["بخش‌هایی از مواد غذایی گیاهی که بدن آن‌ها را به طور کامل هضم نمی‌کند و به کارکرد دستگاه گوارش کمک می‌کنند.","Dietary fibre; parts of plant foods that are not fully digested and help support digestive function.","الألياف الغذائية؛ أجزاء من الأغذية النباتية لا يهضمها الجسم بالكامل وتساعد على عمل الجهاز الهضمي."],
 "چاشنی":["ماده‌ای مانند ادویه، سبزی یا سس که برای بهتر کردن طعم و عطر غذا به آن افزوده می‌شود.","A seasoning or condiment, such as a spice, herb, or sauce, added to improve food's flavour or aroma.","مُنكّه أو إضافة مثل التوابل أو الأعشاب أو الصلصة تُضاف لتحسين طعم الطعام أو رائحته."],
 "سحری":["غذایی که مسلمانان پیش از سپیده‌دم و آغاز روزه در ماه رمضان می‌خورند.","Suhoor; the pre-dawn meal eaten by Muslims before beginning the daily fast in Ramadan.","السحور؛ الوجبة التي يتناولها المسلمون قبل الفجر وقبل بدء صيام يوم رمضان."],
 "طبل‌زنی":["نواختن طبل با دست یا چوب برای ایجاد ریتم، اعلام رویداد یا همراهی با مراسم.","Drumming; playing a drum by hand or with sticks to create rhythm or accompany an event or ceremony.","قرع الطبول؛ العزف على الطبل باليد أو بالعصي لإيجاد إيقاع أو مرافقة مناسبة."],
 "نماز جماعت":["نمازی که گروهی از مسلمانان با اقتدا به یک امام و به صورت هماهنگ می‌خوانند.","Congregational prayer; a prayer performed together by Muslims following an imam.","صلاة الجماعة؛ صلاة يؤدّيها المسلمون معاً مقتدين بإمام."],
 "چراغانی کردن":["یک مکان یا خیابان را با چراغ‌ها و نورهای رنگارنگ برای جشن یا مناسبت ویژه تزئین کردن.","To decorate a place or street with lights and colourful illumination for a celebration or special occasion.","زيّنَ مكاناً أو شارعاً بالأضواء والمصابيح الملوّنة احتفالاً بمناسبة خاصة."],
 "تقسیم کردن":["چیزی را به بخش‌ها یا سهم‌های جداگانه تقسیم و میان افراد یا گروه‌ها پخش کردن.","To divide something into separate parts or shares and distribute them among people or groups.","قسّمَ شيئاً إلى أجزاء أو حصص منفصلة ووزّعها بين أشخاص أو جماعات."],
 "قندپهلو":["نوعی شیرینی یا خوراکی سنتی که با قند یا شکر تهیه می‌شود؛ در برخی کاربردها نام خوراکی محلی است و معنای دقیق به بافت درس بستگی دارد.","A traditional sweet or confection made with sugar; in some contexts, a local speciality whose precise meaning depends on the lesson.","حلوى أو مأكول تقليدي يُحضّر بالسكر؛ وقد يكون اسماً لحلوى محلية ويتحدّد المقصود بحسب سياق الدرس."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH11=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 12. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "مراسم سوم، هفتم و چهلم":["مراسم یادبود در روزهای سوم، هفتم و چهلم پس از درگذشت فرد که در برخی سنت‌ها برای دعا و گرامی‌داشت او برگزار می‌شود.","Memorial observances on the third, seventh, and fortieth days after a person's death, held in some traditions for prayer and remembrance.","مراسم تأبين تُقام في الأيام الثالث والسابع والأربعين بعد وفاة شخص، للدعاء وإحياء ذكراه في بعض التقاليد."],
 "استکان کمرباریک":["لیوان کوچک مخصوص چای که بخش میانی آن باریک‌تر از بالا و پایین است.","A narrow-waisted tea glass whose middle is slimmer than its upper and lower parts.","كأس شاي صغير يضيق وسطه مقارنةً بأعلاه وأسفله."],
 "پایهٔ استکان":["زیرلیوانی یا نگهدارنده‌ای که استکان روی آن قرار می‌گیرد.","A tea-glass saucer or holder on which a small tea glass is placed.","قاعدة أو صحن صغير يوضع عليه كأس الشاي."],
 "سماور زغالی":["سماوری که آب آن با سوختن زغال گرم می‌شود.","A charcoal samovar; a traditional water boiler heated by burning charcoal.","سماور يعمل بالفحم؛ وعاء تقليدي لتسخين الماء بواسطة احتراق الفحم."],
 "قوری چینی":["قوری ساخته‌شده از چینی یا ظروف سرامیکی ظریف که برای دم کردن و ریختن چای به کار می‌رود.","A porcelain teapot used for brewing and pouring tea.","إبريق شاي مصنوع من الخزف الصيني يُستعمل لنقع الشاي وصبّه."],
 "چای سبز":["نوعی چای که برگ‌های آن پس از چیدن کمتر اکسید می‌شوند و رنگ و طعم متفاوتی از چای سیاه دارد.","Green tea, made from leaves that undergo minimal oxidation after harvesting.","الشاي الأخضر؛ نوع من الشاي تتعرّض أوراقه لأكسدة قليلة بعد قطفها."],
 "مرسوم":["رایج و معمول در میان مردم یا مطابق با سنت و عرف یک جامعه.","Customary or customary practice; common among people or in accordance with a community's tradition.","مألوف أو متعارف عليه بين الناس أو وفق تقاليد المجتمع وأعرافه."],
 "دم کشیدن":["ماندن چای یا گیاه در آب داغ برای آزاد شدن عطر و طعم آن؛ همچنین جا افتادن و آماده شدن غذا.","For tea or herbs to steep in hot water and release their flavour; also, for a dish to finish cooking.","نقع الشاي أو الأعشاب في الماء الساخن لإطلاق النكهة والرائحة؛ ويقال أيضاً عن نضج الطعام واكتمال طهيه."],
 "شورشی":["کسی که علیه حکومت، قدرت یا نظم موجود دست به شورش می‌زند؛ همچنین مربوط به شورش.","A rebel or insurgent; someone who rises against an authority or established order.","متمرّد أو ثائر؛ شخص ينهض ضد سلطة أو نظام قائم."],
 "رأفت":["مهربانی و دلسوزی همراه با نرم‌خویی، به‌ویژه در برخورد با فرد خطاکار یا نیازمند.","Compassion or clemency; kindness and mercy, especially toward someone at fault or in need.","رأفة ورحمة؛ لطف وشفقة مقرونتان باللين، ولا سيّما تجاه المخطئ أو المحتاج."],
 "فراگیری":["گستردگی و شامل بودن؛ همچنین فرایند یاد گرفتن و کسب دانش یا مهارت، با توجه به بافت.","Comprehensiveness or breadth; also the process of learning and acquiring knowledge or skills, depending on context.","الشمول والاتساع؛ ويأتي أيضاً بمعنى عملية التعلّم واكتساب المعرفة أو المهارات بحسب السياق."],
 "قومی":["مربوط به یک قوم، گروه قومی یا ویژگی‌های فرهنگی و زبانی آن گروه.","Ethnic or tribal; relating to a people, ethnic group, or its cultural and linguistic characteristics.","قومي أو إثني؛ متعلق بشعب أو جماعة إثنية أو بخصائصها الثقافية واللغوية."],
 "توهین":["سخن یا رفتاری که موجب تحقیر، بی‌احترامی یا رنجاندن شخص دیگری شود.","An insult or offence; words or behaviour that humiliate, disrespect, or hurt another person.","إهانة؛ قول أو سلوك يسبّب تحقيراً أو عدم احترام أو جرحاً لشخص آخر."],
 "متعلق":["وابسته یا مربوط به شخص یا چیزی؛ چیزی که مالک یا صاحب آن فرد یا نهادی است.","Belonging to or related to someone or something; owned by a person or organisation.","تابع أو مرتبط بشخص أو شيء؛ وما يكون مملوكاً لفرد أو مؤسسة."],
 "جمجمه":["استخوان‌بندی سر که از مغز محافظت می‌کند و شکل اصلی سر را می‌سازد.","The skull; the bony structure of the head that protects the brain.","الجمجمة؛ الهيكل العظمي للرأس الذي يحمي الدماغ ويشكّل بنية الرأس."],
 "سفال":["ظروف یا اشیایی که از گل رس ساخته و در کوره پخته می‌شوند.","Pottery or earthenware; objects made from clay and fired in a kiln.","الفخّار؛ أوانٍ أو أشياء تُصنع من الطين وتُحرق في الفرن."],
 "نقش":["وظیفه یا جایگاه یک شخص در کاری؛ همچنین طرح یا تصویری که روی سطحی ایجاد می‌شود.","A role or function played by someone; also, a design or pattern made on a surface.","دور أو وظيفة يؤديها شخص؛ ويعني أيضاً رسماً أو زخرفة على سطح."],
 "قبیله":["گروهی از خانواده‌ها یا تیره‌ها که پیوند خویشاوندی، تاریخی یا فرهنگی مشترک دارند.","A tribe; a group of families or clans connected by kinship, history, or shared culture.","قبيلة؛ جماعة من الأسر أو العشائر تربطها صلات قرابة أو تاريخ أو ثقافة مشتركة."],
 "هیدروسفالی":["عارضه‌ای پزشکی که در آن مایع مغزی‌نخاعی بیش از حد در حفره‌های مغز جمع می‌شود و می‌تواند به مغز فشار وارد کند.","Hydrocephalus; a medical condition in which excess cerebrospinal fluid accumulates in the brain's ventricles and may increase pressure on the brain.","استسقاء الدماغ؛ حالة طبية يتراكم فيها السائل الدماغي الشوكي بكمية زائدة في بطينات الدماغ وقد يسبّب ضغطاً عليه."],
 "راه ریلی":["مسیر یا شبکه‌ای از خطوط آهن که قطارها برای جابه‌جایی مسافر یا بار در آن حرکت می‌کنند.","A railway route or rail network used by trains to transport passengers or freight.","مسار أو شبكة سكك حديدية تسير عليها القطارات لنقل الركاب أو البضائع."],
 "پارچهٔ ابریشمی":["پارچه‌ای نرم و معمولاً براق که از الیاف ابریشم بافته شده است.","Silk fabric; a soft, often lustrous textile woven from silk fibres.","قماش حريري؛ نسيج ناعم ولامع غالباً يُحاك من ألياف الحرير."],
 "پرندهٔ زینتی":["پرنده‌ای که بیشتر به دلیل زیبایی، رنگ یا آواز برای نگهداری و تماشا پرورش داده می‌شود.","An ornamental or pet bird kept mainly for its beauty, colours, or song.","طائر زينة يُربّى أساساً لجماله أو ألوانه أو تغريده."],
 "ایمن":["در برابر خطر، آسیب یا تهدید محافظت‌شده؛ بی‌خطر یا دارای امنیت کافی.","Safe or secure; protected from danger, harm, or threat.","آمن؛ محميّ من الخطر أو الضرر أو التهديد."],
 "صلح":["نبود جنگ و درگیری و برقراری رابطه‌ای آرام و همراه با سازش میان افراد یا گروه‌ها.","Peace; the absence of war or conflict and the establishment of calm, cooperative relations.","السلام؛ غياب الحرب والنزاع وإقامة علاقات هادئة قائمة على التفاهم بين الأفراد أو الجماعات."],
 "تشکیل دادن":["چیزی را از اجزا یا افراد مختلف پدید آوردن و سازمان یا مجموعه‌ای را ایجاد کردن.","To form or constitute something by bringing different parts or people together.","شكّلَ أو كوّنَ شيئاً بجمع أجزاء أو أشخاص مختلفين."],
 "جلوگیری کردن":["مانع رخ دادن کاری شدن یا نگذارد شخص یا چیزی به نتیجه‌ای برسد.","To prevent or stop something from happening or someone from reaching an outcome.","منعَ حدوث أمر أو حالَ دون وصول شخص أو شيء إلى نتيجة."],
 "متصل کردن":["دو یا چند چیز را به هم پیوند دادن تا ارتباط یا اتصال میان آن‌ها برقرار شود.","To connect or link two or more things so that they become joined.","وصلَ شيئين أو أكثر بعضهما ببعض لإقامة اتصال بينها."],
 "فرستادن":["چیزی یا کسی را به سوی مقصد یا شخصی دیگر روانه کردن؛ ارسال کردن.","To send or dispatch a person or thing to a destination or another person.","أرسلَ شخصاً أو شيئاً إلى جهة أو شخص آخر."],
 "پوزه":["بخش جلویی سر برخی جانوران که بینی، دهان و آرواره‌ها را در بر می‌گیرد.","The muzzle or snout; the projecting front part of an animal's head containing its nose, mouth, and jaws.","الخطم أو مقدمة فم الحيوان؛ الجزء الأمامي البارز من الرأس ويضم الأنف والفم والفكين."],
 "اندام":["بخش مشخصی از بدن انسان یا جانور؛ در کاربردی دیگر، عضو یا دستگاهی از بدن که وظیفه‌ای دارد.","A body part or organ; a distinct part of a human or animal body, sometimes referring to a functional organ.","عضو أو جزء من الجسم؛ جزء محدّد من جسم الإنسان أو الحيوان، وقد يُقصد به عضو يؤدي وظيفة."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH12=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 13. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "پر":["پوشش سبک و نرمی که بدن پرندگان را می‌پوشاند؛ همچنین در کاربردی دیگر به معنی سرشار یا لبریز.","A feather; the light, soft covering of a bird. In another use, it can mean full or filled.","ريش؛ الغطاء الخفيف والناعم الذي يكسو جسم الطيور. ويأتي في استعمال آخر بمعنى ممتلئ."],
 "فلس":["پول خرد یا واحد کوچک پول در برخی کشورها؛ همچنین پولک نازک روی پوست ماهی.","A small monetary unit or coin in some countries; also, a fish scale.","فلس؛ وحدة نقدية صغيرة أو قطعة نقدية في بعض البلدان، ويعني أيضاً حرشفة السمك."],
 "نسل":["گروهی از انسان‌ها یا موجودات که در یک دورهٔ زمانی به دنیا آمده‌اند؛ همچنین تبار و زادگان.","A generation of people or organisms born around the same period; also, lineage or descendants.","جيل من البشر أو الكائنات وُلدوا في فترة زمنية متقاربة؛ ويعني أيضاً النسل والذرية."],
 "خشک‌سالی":["دوره‌ای طولانی با بارندگی بسیار کم که باعث کمبود آب و آسیب به کشاورزی و محیط زیست می‌شود.","Drought; a prolonged period of unusually low rainfall that causes water shortages and harms agriculture and ecosystems.","الجفاف؛ فترة طويلة يقلّ فيها هطول الأمطار بصورة كبيرة، فتسبّب نقص المياه والضرر للزراعة والبيئة."],
 "کمبود غذا":["وضعیتی که در آن مقدار غذای در دسترس برای تأمین نیازهای مردم کافی نیست.","Food shortage; a situation in which available food is insufficient to meet people's needs.","نقص الغذاء؛ حالة لا تكفي فيها كمية الطعام المتاحة لتلبية احتياجات الناس."],
 "آلودگی":["وجود مواد یا عوامل زیان‌آور در هوا، آب، خاک یا محیط که سلامت موجودات زنده را تهدید می‌کند.","Pollution or contamination; the presence of harmful substances in air, water, soil, or the environment.","التلوث؛ وجود مواد أو عوامل ضارة في الهواء أو الماء أو التربة أو البيئة تهدّد صحة الكائنات الحية."],
 "زهر":["ماده‌ای سمی که می‌تواند به بدن انسان یا جانور آسیب برساند؛ همچنین مایع سمی برخی جانوران.","Poison or venom; a toxic substance that can harm humans or animals.","سمّ؛ مادة سامة قد تضرّ بالإنسان أو الحيوان، ويُطلق أيضاً على السم الذي تفرزه بعض الحيوانات."],
 "داروسازی":["دانش و صنعت تهیه، تولید، بررسی و عرضهٔ داروها برای پیشگیری یا درمان بیماری‌ها.","Pharmacy or pharmaceutical science; the science and industry of preparing, producing, testing, and supplying medicines.","الصيدلة؛ علم وصناعة تحضير الأدوية وإنتاجها وفحصها وتوفيرها للوقاية من الأمراض أو علاجها."],
 "موجود زنده":["هر جانداری که ویژگی‌های حیات مانند رشد، سوخت‌وساز و پاسخ به محیط را دارد.","A living organism; any being that exhibits life processes such as growth, metabolism, and response to its environment.","كائن حي؛ كل مخلوق تظهر عليه مظاهر الحياة مثل النمو والأيض والاستجابة للبيئة."],
 "جوندگان":["گروهی از پستانداران که دندان‌های پیشین آن‌ها برای جویدن و ساییدن رشد پیوسته دارد؛ مانند موش و سنجاب.","Rodents; mammals whose continuously growing front teeth are adapted for gnawing, such as mice and squirrels.","القوارض؛ ثدييات تتميّز بأسنان أمامية تستمر في النمو ومهيّأة للقرض، مثل الفئران والسناجب."],
 "گودال":["فرورفتگی یا حفره‌ای در زمین یا سطحی دیگر.","A pit, hole, or depression in the ground or another surface.","حفرة أو انخفاض في الأرض أو في سطح آخر."],
 "حقه‌باز":["کسی که با فریب، نیرنگ یا ترفند دیگران را گمراه می‌کند یا از آن‌ها سود می‌برد.","A trickster or swindler; someone who deceives others through tricks or fraud.","مخادع أو محتال؛ شخص يضلّل الآخرين بالحيل أو الخداع لتحقيق مصلحة."],
 "تقلید":["پیروی یا بازآفرینی گفتار، رفتار، سبک یا شیوهٔ شخص یا چیزی دیگر.","Imitation; copying or reproducing another person's speech, behaviour, style, or method.","تقليد؛ محاكاة كلام شخص أو سلوكه أو أسلوبه أو طريقته."],
 "مجاز":["آنچه طبق قانون، قاعده یا اجازه‌ای رسمی یا عرفی پذیرفته و ممنوع نیست.","Permitted or authorised; allowed under a law, rule, or formal or customary permission.","مسموح أو مأذون به؛ ما تجيزه القوانين أو القواعد أو الموافقة الرسمية أو العرفية."],
 "خش‌خش":["صدای آرام و پیوسته‌ای که از مالیده شدن یا حرکت چیزهایی مانند برگ خشک و کاغذ ایجاد می‌شود.","A rustling or crackling sound made by the movement or friction of things such as dry leaves or paper.","حفيف أو خشخشة؛ صوت هادئ متتابع ينتج عن احتكاك أو حركة أشياء مثل الأوراق اليابسة أو الورق."],
 "تق‌تق":["صدای کوتاه و تکرارشونده‌ای که از ضربه‌های سبک یا برخورد اجسام ایجاد می‌شود.","A repeated light tapping or clicking sound caused by small impacts or objects striking one another.","طقطقة أو نقر متكرر وخفيف ينتج عن ضربات صغيرة أو اصطدام الأشياء."],
 "خرخر":["صدای تنفس بلند و لرزانی که معمولاً هنگام خواب ایجاد می‌شود؛ همچنین صدای آرام برخی جانوران.","Snoring; a rough, vibrating breathing sound usually made during sleep. It can also describe a low sound made by some animals.","شخير؛ صوت تنفّس خشن و مهتزّ يصدر غالباً أثناء النوم، ويُستعمل أيضاً لصوت منخفض تصدره بعض الحيوانات."],
 "یوزپلنگ":["جانوری گوشت‌خوار و بسیار تندرو از خانوادهٔ گربه‌سانان که بدن باریک و لکه‌های سیاه دارد.","A cheetah; a very fast-running carnivorous member of the cat family with a slender body and black spots.","الفهد الصيّاد؛ حيوان لاحم سريع جداً من فصيلة السنوريات، جسمه نحيل وعليه بقع سوداء."],
 "خالدار":["دارای خال‌ها یا لکه‌های کوچک و مشخص روی سطح یا بدن.","Spotted or speckled; marked with small, distinct spots.","مبقّع؛ عليه نقاط أو بقع صغيرة وواضحة."],
 "بومی":["وابسته به یک منطقه یا سرزمین و متعلق به همان‌جا از نظر پیدایش یا زندگی؛ محلی و native.","Native or indigenous; originating in or naturally belonging to a particular region.","محلي أو أصلي؛ ينتمي بطبيعته أو نشأته إلى منطقة أو أرض معيّنة."],
 "شکار کردن":["جانوری را برای غذا یا هدفی دیگر تعقیب و گرفتن یا کشتن؛ همچنین در معنای گسترده‌تر به دنبال شکار رفتن.","To hunt; to pursue and capture or kill an animal for food or another purpose.","اصطادَ؛ طاردَ حيواناً وأمسكه أو قتله للطعام أو لغرض آخر."],
 "باقی ماندن":["پس از تغییر، گذشت زمان یا از بین رفتن بخش‌های دیگر همچنان وجود داشتن یا حفظ شدن.","To remain or survive; to continue to exist after change, the passage of time, or the loss of other parts.","بقيَ أو استمرّ في الوجود بعد التغيير أو مرور الزمن أو زوال أجزاء أخرى."],
 "قطع کردن":["چیزی را بریدن یا پیوستگی آن را متوقف کردن؛ مانند قطع کردن طناب، برق یا تماس.","To cut something or interrupt its continuity, such as cutting a rope or disconnecting power or a call.","قطعَ شيئاً أو أوقفَ استمراره، مثل قطع حبل أو الكهرباء أو الاتصال."],
 "وضو گرفتن":["برای انجام عبادت‌هایی مانند نماز، اعضای مشخصی از بدن را با آب به ترتیب شرعی شستن یا مسح کردن.","To perform wudu, the prescribed Islamic ablution involving washing or wiping specific parts of the body before prayer.","توضّأ؛ غسلَ أو مسحَ أعضاء محدّدة من الجسم وفق الطريقة الشرعية استعداداً للصلاة."],
 "کود شیمیایی":["ماده‌ای صنعتی یا معدنی که برای تأمین عناصر غذایی مورد نیاز گیاه به خاک افزوده می‌شود.","A chemical fertiliser applied to soil to supply nutrients needed by plants.","سماد كيميائي يُضاف إلى التربة لتزويد النباتات بالعناصر الغذائية اللازمة."],
 "سم شیمیایی":["ماده‌ای شیمیایی سمی که برای از بین بردن آفت‌ها یا موجودات زیان‌آور به کار می‌رود و در صورت استفادهٔ نادرست می‌تواند خطرناک باشد.","A chemical poison or pesticide used to kill pests or harmful organisms; it can be dangerous if misused.","مادة كيميائية سامة تُستعمل للقضاء على الآفات أو الكائنات الضارة، وقد تكون خطرة إذا أسيء استخدامها."],
 "زبالهٔ تر":["پسماندهای مرطوب و معمولاً آلی، مانند باقی‌ماندهٔ غذا و پوست میوه، که قابلیت تجزیه دارند.","Wet waste; moist, usually organic rubbish such as food scraps and fruit peels that can decompose.","النفايات الرطبة؛ مخلفات رطبة وعضوية غالباً، مثل بقايا الطعام وقشور الفاكهة، قابلة للتحلّل."],
 "زبالهٔ خشک":["پسماندهای کم‌رطوبت مانند کاغذ، پلاستیک، فلز و شیشه که بسیاری از آن‌ها قابل بازیافت‌اند.","Dry waste; low-moisture rubbish such as paper, plastic, metal, and glass, much of which can be recycled.","النفايات الجافة؛ مخلفات قليلة الرطوبة مثل الورق والبلاستيك والمعادن والزجاج، وكثير منها قابل لإعادة التدوير."],
 "تفکیک زباله":["جدا کردن پسماندها بر اساس نوع و جنس، مانند مواد تر، خشک و قابل بازیافت، برای مدیریت بهتر آن‌ها.","Waste sorting; separating rubbish by type, such as wet, dry, and recyclable materials, for better management.","فرز النفايات؛ فصل المخلفات بحسب نوعها، مثل الرطبة والجافة والقابلة لإعادة التدوير، لتحسين إدارتها."],
 "ته‌سیگار":["بخش باقی‌ماندهٔ سیگار پس از سوختن و کشیدن آن که معمولاً دور انداخته می‌شود.","A cigarette butt; the remaining end of a cigarette after it has been smoked.","عقب السيجارة؛ الجزء المتبقي من السيجارة بعد تدخينها."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH13=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 14. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "بطری پلاستیکی":["ظرفی از جنس پلاستیک، معمولاً برای نگهداری و حمل آب یا نوشیدنی‌های دیگر.","A plastic bottle; a container made of plastic, commonly used to store and carry water or other drinks.","زجاجة بلاستيكية؛ وعاء مصنوع من البلاستيك يُستعمل عادةً لحفظ الماء أو المشروبات ونقلها."],
 "بازیافت":["فرایند جمع‌آوری و پردازش مواد دورریختنی برای تبدیل آن‌ها به مواد یا محصولات قابل استفادهٔ دوباره.","Recycling; collecting and processing discarded materials so they can be made into reusable materials or products.","إعادة التدوير؛ جمع المواد المستعملة ومعالجتها لتحويلها إلى مواد أو منتجات قابلة للاستعمال مجدداً."],
 "آتش‌سوزی جنگل":["سوختن گسترده و کنترل‌نشدهٔ پوشش گیاهی در جنگل یا مراتع که می‌تواند به طبیعت و جانوران آسیب بزند.","A forest fire or wildfire; an uncontrolled fire spreading through woodland or vegetation and damaging ecosystems.","حريق غابات؛ حريق واسع وغير مسيطر عليه ينتشر في الغابات أو النباتات وقد يضرّ بالنظم البيئية."],
 "کرم ابریشم":["لارو پروانه‌ای که از برگ توت تغذیه می‌کند و پیله‌ای از رشته‌های ابریشم می‌سازد.","A silkworm; the larva of a moth that feeds on mulberry leaves and spins a silk cocoon.","دودة القز؛ يرقة فراشة تتغذّى على أوراق التوت وتنسج شرنقة من خيوط الحرير."],
 "پیله":["پوشش رشته‌ای که کرم ابریشم یا برخی حشرات در مرحله‌ای از رشد به دور خود می‌تنند.","A cocoon; a protective casing of silk or fibres spun by a silkworm or other insect during development.","شرنقة؛ غلاف واقٍ من الحرير أو الألياف تنسجه دودة القز أو بعض الحشرات خلال نموّها."],
 "شن روان":["توده‌ای از شن نرم و جابه‌جاشونده که بر اثر باد یا حرکت روی سطح زمین تغییر مکان می‌دهد.","Shifting or drifting sand; loose sand that moves across the ground, often under the force of wind.","رمال متحرّكة؛ كتل من الرمل الناعم تنتقل على سطح الأرض بفعل الرياح أو الحركة."],
 "باتلاق":["زمین مرطوب و گِلی که آب در آن جمع می‌شود و حرکت در آن دشوار است.","A swamp or bog; wet, muddy land where water collects and movement may be difficult.","مستنقع أو أرض موحلة رطبة تتجمّع فيها المياه ويصعب السير فيها."],
 "افسانه":["داستانی سنتی یا خیالی که گاه عناصر شگفت‌انگیز دارد و نسل به نسل نقل می‌شود.","A legend or fable; a traditional or imaginative story, sometimes containing extraordinary elements, passed down over generations.","أسطورة أو حكاية؛ قصة تراثية أو خيالية قد تضمّ عناصر عجيبة وتتناقلها الأجيال."],
 "ساده‌سازی":["کم کردن پیچیدگی یک موضوع، فرایند یا متن برای آسان‌تر شدن فهم یا انجام آن.","Simplification; reducing the complexity of a subject, process, or text to make it easier to understand or carry out.","التبسيط؛ تقليل تعقيد موضوع أو عملية أو نصّ لتسهيل فهمه أو تنفيذه."],
 "درخت توت":["درختی که میوه‌های توت می‌دهد و برگ‌های آن غذای اصلی کرم ابریشم است.","A mulberry tree; a tree that bears mulberries and whose leaves are the main food of silkworms.","شجرة التوت؛ شجرة تُثمر التوت وتُعدّ أوراقها الغذاء الأساسي لدودة القز."],
 "جمع‌آوری کردن":["چیزهای پراکنده را گرد آوردن و در یک جا قرار دادن؛ مانند گردآوری زباله یا اطلاعات.","To collect or gather scattered items and bring them together, such as waste or information.","جمعَ أشياء متفرّقة ووضعها في مكان واحد، مثل النفايات أو المعلومات."],
 "بافتن":["با درهم‌گذراندن نخ‌ها یا رشته‌ها پارچه، فرش یا چیزی مشابه پدید آوردن.","To weave or knit by interlacing threads or strands to make fabric, a carpet, or a similar item.","نسجَ أو حاكَ بتشابك الخيوط لصنع قماش أو سجادة أو شيء مشابه."],
 "سوخت فسیلی":["سوختی مانند نفت، گاز طبیعی یا زغال‌سنگ که از بقایای جانداران بسیار قدیمی در زمین به وجود آمده است.","A fossil fuel, such as oil, natural gas, or coal, formed from the remains of ancient organisms.","وقود أحفوري مثل النفط أو الغاز الطبيعي أو الفحم، تكوّن من بقايا كائنات حيّة قديمة."],
 "زغال‌سنگ":["ماده‌ای سنگی و سیاه‌رنگ که از کربن فراوان تشکیل شده و به عنوان سوخت فسیلی مصرف می‌شود.","Coal; a carbon-rich black rock used as a fossil fuel.","الفحم الحجري؛ صخر أسود غنيّ بالكربون يُستعمل وقوداً أحفورياً."],
 "انرژی برق‌آبی":["انرژی الکتریکی تولیدشده با استفاده از نیروی جریان یا سقوط آب برای چرخاندن توربین‌ها.","Hydroelectric power; electricity generated by using flowing or falling water to drive turbines.","الطاقة الكهرومائية؛ كهرباء تُنتَج باستعمال تدفّق الماء أو سقوطه لتدوير التوربينات."],
 "انرژی بادی":["انرژی‌ای که از حرکت باد و معمولاً با چرخاندن پره‌های توربین بادی به برق تبدیل می‌شود.","Wind energy; energy captured from moving air, often converted into electricity by wind turbines.","طاقة الرياح؛ طاقة تُستمدّ من حركة الهواء وتُحوّل غالباً إلى كهرباء بواسطة توربينات الرياح."],
 "اورانیوم":["عنصری شیمیایی و فلزی سنگین و پرتوزا که برخی ایزوتوپ‌های آن به عنوان سوخت در نیروگاه‌های هسته‌ای به کار می‌روند.","Uranium; a heavy radioactive chemical element whose isotopes are used as fuel in some nuclear power plants.","اليورانيوم؛ عنصر كيميائي فلزي ثقيل ومشعّ تُستعمل بعض نظائره وقوداً في محطات الطاقة النووية."],
 "توربین":["ماشینی با پره‌های چرخان که انرژی جریان آب، بخار، گاز یا باد را به حرکت مکانیکی تبدیل می‌کند.","A turbine; a machine with rotating blades that converts the energy of water, steam, gas, or wind into mechanical motion.","توربين؛ آلة ذات شفرات دوّارة تحوّل طاقة الماء أو البخار أو الغاز أو الرياح إلى حركة ميكانيكية."],
 "نیروگاه":["مجموعه‌ای صنعتی که انرژی را به برق تبدیل می‌کند؛ مانند نیروگاه آبی، بادی، حرارتی یا هسته‌ای.","A power plant or generating station; an industrial facility that converts energy into electricity.","محطة توليد الطاقة؛ منشأة صناعية تحوّل مصادر الطاقة إلى كهرباء، مثل المحطات المائية والريحية والحرارية والنووية."],
 "لامپ کم‌مصرف":["لامپی که برای تولید مقدار معینی نور، برق کمتری نسبت به لامپ‌های پرمصرف قدیمی استفاده می‌کند.","An energy-saving light bulb that uses less electricity than older, less efficient bulbs to produce a similar amount of light.","مصباح موفّر للطاقة يستهلك كهرباء أقل من المصابيح القديمة الأقل كفاءة لإنتاج مقدار مماثل من الضوء."],
 "پردهٔ ضخیم":["پرده‌ای از پارچهٔ سنگین یا چندلایه که نور را کمتر عبور می‌دهد و به حفظ گرما یا حریم خصوصی کمک می‌کند.","A thick curtain made of heavy or layered fabric that blocks more light and helps retain heat or provide privacy.","ستارة سميكة من قماش ثقيل أو متعدد الطبقات تحجب الضوء وتساعد على حفظ الحرارة أو الخصوصية."],
 "وان":["ظرف بزرگ و عمیقی در حمام که برای نشستن یا دراز کشیدن و شست‌وشو در آب استفاده می‌شود.","A bathtub; a large, deep bathroom container used for bathing in water.","حوض الاستحمام؛ وعاء كبير وعميق في الحمّام يُستعمل للاستحمام بالماء."],
 "دوش":["وسیله یا روش شست‌وشوی بدن با پاشیدن آب از سردوش؛ همچنین خودِ جریان آب.","A shower; a device or method for washing the body with sprayed water.","دُشّ أو حمّام؛ وسيلة لغسل الجسم برشّ الماء، ويُطلق أيضاً على تدفّق الماء نفسه."],
 "شیر آب":["وسیله‌ای روی لوله که با باز و بسته کردن آن جریان آب کنترل می‌شود.","A water tap or faucet; a valve used to control the flow of water from a pipe.","صنبور الماء؛ صمام يُفتح ويُغلق للتحكّم في تدفّق الماء من الأنبوب."],
 "جریمه":["مجازات مالی یا مبلغی که به دلیل تخلف یا نقض قانون باید پرداخت شود.","A fine or penalty; money that must be paid as punishment for an offence or rule violation.","غرامة؛ مبلغ مالي يجب دفعه عقوبةً على مخالفة أو انتهاك قانون."],
 "باز گذاشتن":["چیزی مانند در، پنجره یا شیر را در حالت باز قرار دادن و نبستن.","To leave something open, such as a door, window, or tap.","تركَ شيئاً مفتوحاً، مثل الباب أو النافذة أو صنبور الماء."],
 "جریمه کردن":["برای تخلف، شخص یا نهادی را ملزم به پرداخت جریمه کردن.","To fine or penalise a person or organisation by requiring payment for an offence.","غرّمَ شخصاً أو مؤسسة وألزمه بدفع غرامة بسبب مخالفة."],
 "آموزش دادن":["دانش، مهارت یا روشی را به دیگران یاد دادن و به فهم یا تمرین آن‌ها کمک کردن.","To teach or instruct others by helping them learn knowledge, skills, or methods.","علّمَ الآخرين وساعدهم على اكتساب المعرفة أو المهارات أو الأساليب وممارستها."],
 "قمار":["بازی یا فعالیتی که در آن پول یا دارایی بر نتیجه‌ای نامطمئن شرط‌بندی می‌شود.","Gambling; an activity in which money or property is wagered on an uncertain outcome.","القمار؛ نشاط تُراهن فيه الأموال أو الممتلكات على نتيجة غير مؤكدة."],
 "مشروبات الکلی":["نوشیدنی‌هایی که حاوی الکل اتیلیک هستند؛ مانند آبجو، شراب و نوشیدنی‌های تقطیری.","Alcoholic beverages; drinks containing ethyl alcohol, such as beer, wine, and spirits.","المشروبات الكحولية؛ مشروبات تحتوي على الكحول الإيثيلي، مثل الجعة والنبيذ والمشروبات المقطّرة."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH14=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 15. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "غیرقانونی":["خلاف قانون یا مقررات رسمی؛ کاری که انجام آن از نظر قانون ممنوع است.","Illegal or unlawful; contrary to the law or official regulations.","غير قانوني؛ مخالف للقانون أو الأنظمة الرسمية، ويُمنع فعله بموجب القانون."],
 "حداکثر سرعت":["بیشترین سرعت مجاز یا تعیین‌شده برای حرکت وسیلهٔ نقلیه در یک مسیر.","The maximum speed or speed limit permitted for vehicles on a particular road.","السرعة القصوى؛ أعلى سرعة مسموح بها أو محدّدة لسير المركبات على طريق معيّن."],
 "خیابان یک‌طرفه":["خیابانی که خودروها در آن فقط اجازه دارند در یک جهت مشخص حرکت کنند.","A one-way street; a road on which vehicles may travel in only one direction.","شارع باتجاه واحد؛ طريق يُسمح للمركبات بالسير فيه في اتجاه محدّد واحد فقط."],
 "ورود ممنوع":["تابلویی راهنمایی و رانندگی که ورود وسایل نقلیه یا افراد را به مسیر یا مکان مشخص منع می‌کند.","No entry; a traffic sign prohibiting vehicles or people from entering a particular road or area.","ممنوع الدخول؛ إشارة مرورية تمنع المركبات أو الأشخاص من دخول طريق أو منطقة معيّنة."],
 "خط ممتد":["خط پیوسته و بدون شکست روی سطح راه که رانندگان معمولاً نباید از آن عبور کنند.","A solid line marking on a road, which drivers are generally not permitted to cross.","خط متصل على سطح الطريق، لا يُسمح للسائقين عادةً بتجاوزه."],
 "عابر پیاده":["شخصی که در خیابان یا مسیر عمومی پیاده حرکت می‌کند و از وسیلهٔ نقلیه استفاده نمی‌کند.","A pedestrian; a person travelling on foot rather than in a vehicle.","مترجّل؛ شخص يسير على قدميه في الشارع أو الطريق العام ولا يستعمل مركبة."],
 "تخلف":["عملی که برخلاف قانون، مقررات یا دستور تعیین‌شده انجام می‌شود.","A violation or offence; an action that breaks a law, regulation, or established rule.","مخالفة؛ فعل يخالف قانوناً أو نظاماً أو قاعدة مقرّرة."],
 "متخلف":["شخصی که قانون، مقررات یا دستور را نقض کرده است.","A violator or offender; someone who has broken a law, regulation, or rule.","مخالف أو مرتكب مخالفة؛ شخص خالف قانوناً أو نظاماً أو قاعدة."],
 "اخراج":["وادار کردن فرد به ترک مدرسه، محل کار، سازمان یا مکانی که در آن حضور داشته است.","Expulsion or dismissal; the act of making someone leave a school, workplace, organisation, or place.","طرد أو فصل؛ إجبار شخص على مغادرة مدرسة أو مكان عمل أو مؤسسة أو مكان كان فيه."],
 "نسخهٔ پزشک":["دستور مکتوب پزشک برای تهیه و مصرف دارو یا انجام درمان مشخص.","A medical prescription; a written instruction from a doctor for obtaining and using medicine or receiving treatment.","وصفة طبية؛ تعليمات مكتوبة من الطبيب لصرف دواء واستعماله أو لتلقّي علاج محدّد."],
 "کارت شناسایی":["مدرکی رسمی یا سازمانی که برای تأیید هویت فرد و نمایش اطلاعات اصلی او صادر می‌شود.","An identity card or ID card issued to verify a person's identity and display basic information.","بطاقة هوية؛ وثيقة رسمية أو مؤسسية لإثبات هوية الشخص وعرض بياناته الأساسية."],
 "حبس":["مجازات یا وضعیت محروم شدن از آزادی و نگهداری فرد در زندان یا محل بازداشت.","Imprisonment or detention; the punishment or condition of being deprived of liberty and held in prison or custody.","الحبس أو السجن؛ عقوبة أو حالة يُحرم فيها الشخص من الحرية ويُحتجز في السجن أو التوقيف."],
 "چرخ پلاستیکی":["چرخی که از پلاستیک ساخته شده و در اسباب‌بازی‌ها، وسایل سبک یا تجهیزات مختلف به کار می‌رود.","A plastic wheel; a wheel made of plastic and used in toys, lightweight devices, or other equipment.","عجلة بلاستيكية؛ عجلة مصنوعة من البلاستيك تُستعمل في الألعاب أو الأجهزة الخفيفة أو معدات أخرى."],
 "کشیش":["روحانی مسیحی که در کلیسا خدمت می‌کند و وظایف دینی مانند برگزاری آیین‌ها را انجام می‌دهد.","A Christian priest; a member of the clergy who serves in a church and performs religious duties.","كاهن مسيحي؛ رجل دين يخدم في الكنيسة ويؤدي الواجبات والطقوس الدينية."],
 "راهبه":["زنی که در یک جامعهٔ دینی مسیحی زندگی می‌کند و زندگی خود را وقف عبادت و خدمت دینی کرده است.","A nun; a woman who belongs to a Christian religious community and devotes her life to prayer and religious service.","راهبة؛ امرأة تنتمي إلى جماعة دينية مسيحية وتكرّس حياتها للعبادة والخدمة الدينية."],
 "شهردار":["مقام مسئول ادارهٔ امور اجرایی و خدمات شهری در یک شهر.","A mayor; the official responsible for the administration and municipal services of a city.","رئيس البلدية؛ المسؤول عن إدارة الشؤون التنفيذية والخدمات البلدية في المدينة."],
 "کارکنان":["افرادی که در یک اداره، سازمان، شرکت یا مجموعه مشغول به کار هستند.","Staff or employees; people who work in an office, organisation, company, or institution.","الموظفون أو العاملون؛ أشخاص يعملون في دائرة أو مؤسسة أو شركة أو هيئة."],
 "سروصدا":["صدای بلند، آزاردهنده یا نامنظمی که آرامش محیط را برهم می‌زند.","Noise or commotion; loud, disturbing, or irregular sound that disrupts a peaceful environment.","ضوضاء أو جلبة؛ صوت مرتفع أو مزعج أو غير منتظم يخلّ بهدوء المكان."],
 "تصغیر":["کوچک شمردن یا کوچک‌تر نشان دادن چیزی؛ در زبان‌شناسی، ساخت واژه‌ای با معنای کوچک یا محبت‌آمیز.","Diminution or making something seem smaller; in linguistics, forming a diminutive word expressing smallness or affection.","التصغير؛ جعل الشيء أصغر أو إظهاره صغيراً، وفي علم اللغة صياغة لفظ يدلّ على الصغر أو التحبّب."],
 "رشوه گرفتن":["در برابر انجام یا ترک یک کار، پول یا امتیازی را به شکل غیرقانونی و پنهانی دریافت کردن.","To take a bribe; to accept money or benefits illegally in exchange for doing or not doing something.","ارتشى؛ تلقّى مالاً أو منفعة بصورة غير قانونية مقابل القيام بعمل أو الامتناع عنه."],
 "رعایت کردن":["به قانون، حق دیگران، دستور یا نکته‌ای توجه و مطابق آن عمل کردن.","To observe, respect, or comply with a rule, right, instruction, or consideration.","راعى أو التزمَ بقانون أو حقّ الآخرين أو تعليمات أو اعتبار معيّن."],
 "چسباندن":["چیزی را با چسب یا فشار به سطح یا شیء دیگری متصل کردن.","To stick or attach something to another surface or object using glue or pressure.","ألصقَ شيئاً بسطح أو جسم آخر باستعمال الغراء أو الضغط."],
 "نصب کردن":["وسیله، تابلو یا تجهیزات را در محل مناسب قرار دادن و ثابت کردن؛ همچنین نرم‌افزار را روی دستگاه آمادهٔ استفاده کردن.","To install or mount equipment, a sign, or a device in place; also, to install software on a device.","ثبّتَ جهازاً أو لوحةً أو معدات في موضعها؛ ويعني أيضاً تثبيت برنامج على جهاز."],
 "بوق زدن":["با فشردن بوق خودرو صدای هشدار یا اعلام حضور ایجاد کردن.","To honk or sound a vehicle's horn as a warning or signal.","أطلقَ بوق المركبة لإصدار صوت تنبيه أو إشارة."],
 "دزدگیر":["دستگاهی که هنگام تلاش برای ورود غیرمجاز یا سرقت، با صدا یا پیام هشدار می‌دهد.","A burglar alarm or security alarm that alerts people by sound or message when unauthorised entry or theft is detected.","جهاز إنذار ضد السرقة يصدر صوتاً أو رسالة تنبيه عند اكتشاف دخول غير مصرّح به أو محاولة سرقة."],
 "واکنش":["پاسخ یا تغییر رفتاری، جسمی یا شیمیایی که در برابر یک محرک یا رویداد رخ می‌دهد.","A reaction or response; a behavioural, physical, or chemical change caused by a stimulus or event.","ردّ فعل أو استجابة؛ تغيّر سلوكي أو جسدي أو كيميائي يحدث نتيجة مؤثّر أو حدث."],
 "غافلگیر":["کسی که از رخدادی غیرمنتظره شگفت‌زده یا آماده‌نبوده است؛ در ترکیب «غافلگیر شدن» به معنی ناگهان شگفت‌زده شدن.","Taken by surprise; unexpectedly astonished or unprepared. Often used in the phrase 'to be surprised'.","مباغَت أو متفاجئ؛ من فوجئ بأمر غير متوقّع أو لم يكن مستعدّاً له."],
 "دلداری":["سخن یا رفتاری آرامش‌بخش برای کم کردن اندوه، نگرانی یا ناراحتی فرد دیگر.","Consolation or comfort; words or actions that ease another person's sadness, worry, or distress.","مواساة أو تعزية؛ كلام أو تصرّف يخفّف حزن شخص آخر أو قلقه أو ضيقه."],
 "بی‌خوابی":["ناتوانی در به خواب رفتن یا ادامهٔ خواب، یا کمبود خواب در حدی که بر زندگی روزانه اثر بگذارد.","Insomnia or sleeplessness; difficulty falling asleep or staying asleep, or insufficient sleep that affects daily life.","الأرق؛ صعوبة الدخول في النوم أو الاستمرار فيه، أو قلّة النوم بما يؤثّر في الحياة اليومية."],
 "سردرد":["درد یا احساس فشار در بخشی از سر یا سراسر آن.","A headache; pain or pressure felt in part or all of the head.","صداع؛ ألم أو إحساس بالضغط في جزء من الرأس أو في الرأس كله."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH15=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 16. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "بدن‌درد":["درد یا کوفتگی در یک یا چند بخش بدن، مانند عضلات و مفاصل.","Body aches; pain or soreness in one or more parts of the body, such as the muscles or joints.","آلام الجسم؛ وجع أو ألم في جزء أو أكثر من الجسم، مثل العضلات أو المفاصل."],
 "سرگیجه":["احساس چرخیدن محیط یا ناپایداری و سبکی سر، به‌گونه‌ای که حفظ تعادل دشوار شود.","Dizziness or vertigo; a sensation of spinning, light-headedness, or unsteadiness that may make balance difficult.","الدوار؛ إحساس بدوران المكان أو خفة الرأس أو عدم الاتزان بما قد يصعّب الحفاظ على التوازن."],
 "خستگی":["کاهش انرژی و توان جسمی یا ذهنی که باعث می‌شود فرد احساس کند به استراحت نیاز دارد.","Fatigue or tiredness; reduced physical or mental energy that makes a person feel in need of rest.","التعب أو الإرهاق؛ انخفاض الطاقة الجسدية أو الذهنية بما يجعل الشخص يشعر بالحاجة إلى الراحة."],
 "نشانه":["علامت یا ویژگی‌ای که وجود یک وضعیت، رویداد یا موضوع را نشان می‌دهد.","A sign or indication; a feature that points to the presence of a condition, event, or subject.","علامة أو دلالة؛ سمة تشير إلى وجود حالة أو حدث أو أمر معيّن."],
 "روان‌پزشک":["پزشکی متخصص که بیماری‌ها و اختلال‌های روانی را ارزیابی و درمان می‌کند.","A psychiatrist; a medical doctor specialising in the assessment and treatment of mental disorders.","طبيب نفسي؛ طبيب متخصص في تقييم الاضطرابات النفسية وعلاجها."],
 "ذکر":["یاد کردن و به زبان یا دل نام خدا را بر زبان آوردن؛ همچنین یادآوری و نام بردن از چیزی.","Dhikr or remembrance; the devotional remembrance of God, and more generally the act of recalling or mentioning something.","الذِّكر؛ استحضار الله وذكره باللسان أو القلب، ويأتي عموماً بمعنى تذكّر شيء أو ذكره."],
 "روایت":["بازگویی یک رویداد یا داستان؛ همچنین نقل سخن یا گزارشی که از فردی به دیگران رسیده است.","Narration or report; recounting an event or story, and also a transmitted account or tradition.","رواية أو نقل؛ سرد حدث أو قصة، ويعني أيضاً خبراً أو أثراً نُقل عن شخص إلى آخرين."],
 "نشاط":["شادابی، سرزندگی و انرژی برای انجام کار؛ همچنین میزان فعالیت و تحرک.","Vigour, vitality, or energy for action; also the level of activity or movement.","النشاط والحيوية والطاقة على العمل؛ ويعني أيضاً مقدار الفعالية والحركة."],
 "رضایت":["احساس خشنودی و پذیرفتن یک وضعیت یا نتیجه؛ همچنین موافقت یا اجازهٔ فرد.","Satisfaction or consent; a feeling of contentment with a situation or result, or a person's agreement or permission.","الرضا أو الموافقة؛ شعور بالارتياح تجاه حالة أو نتيجة، أو قبول الشخص وإذنه."],
 "وقت آزاد":["زمانی که فرد پس از انجام کارها و مسئولیت‌های ضروری برای استراحت یا فعالیت دلخواه در اختیار دارد.","Free time or leisure time; time available after necessary work and responsibilities for rest or chosen activities.","وقت الفراغ؛ الوقت المتاح بعد أداء الأعمال والمسؤوليات الضرورية للراحة أو ممارسة أنشطة يختارها الشخص."],
 "درد و رنج":["احساس‌های جسمی یا روانی ناخوشایند و دشواری‌هایی که موجب ناراحتی و سختی می‌شوند.","Pain and suffering; unpleasant physical or emotional experiences and hardships that cause distress.","الألم والمعاناة؛ تجارب جسدية أو نفسية مؤلمة وصعوبات تسبّب الضيق والمشقّة."],
 "لذت حلال":["خوشی یا بهره‌ای که در چارچوب احکام و ارزش‌های اسلامی مجاز و روا شمرده می‌شود.","Permissible pleasure; enjoyment considered lawful and acceptable within Islamic teachings and values.","متعة مباحة؛ لذّة تُعدّ جائزة ومقبولة ضمن الأحكام والقيم الإسلامية."],
 "آجیل":["مجموعه‌ای از مغزها و دانه‌های خوراکی مانند پسته، بادام، گردو و فندق که گاهی با میوهٔ خشک همراه است.","Nuts or a nut assortment, such as pistachios, almonds, walnuts, and hazelnuts, sometimes mixed with dried fruit.","المكسّرات؛ مجموعة من الحبوب والثمار الصالحة للأكل مثل الفستق واللوز والجوز والبندق، وقد تُخلط بالفواكه المجففة."],
 "ویتامین":["مادهٔ آلی ضروری که بدن برای رشد و عملکرد طبیعی به مقدار کم به آن نیاز دارد و معمولاً از غذا دریافت می‌شود.","A vitamin; an essential organic substance needed in small amounts for normal growth and bodily function, usually obtained from food.","فيتامين؛ مادة عضوية أساسية يحتاج إليها الجسم بكميات قليلة للنمو والوظائف الطبيعية، ويحصل عليها غالباً من الغذاء."],
 "عبادت":["پرستش و بندگی خدا از راه‌هایی مانند نماز، دعا و انجام فرمان‌های دینی.","Worship or devotion to God through practices such as prayer, supplication, and following religious commands.","العبادة؛ التقرّب إلى الله وعبادته بأعمال مثل الصلاة والدعاء وامتثال الأوامر الدينية."],
 "خلوت با خدا":["زمان یا حالتی از تنهایی و توجه قلبی که فرد برای دعا، نیایش و گفت‌وگوی معنوی با خدا در نظر می‌گیرد.","A private moment with God; a period of solitude and inward attention devoted to prayer and spiritual communion.","خلوة مع الله؛ وقت من الانفراد والتوجّه القلبي يخصّصه الإنسان للدعاء والمناجاة الروحية."],
 "غافلگیر کردن":["کسی را با رخدادی غیرمنتظره روبه‌رو کردن، به‌گونه‌ای که برای آن آماده نباشد.","To surprise or catch someone off guard with an unexpected event.","فاجأَ شخصاً بأمر غير متوقّع بحيث لم يكن مستعدّاً له."],
 "آرام شدن":["از شدت هیجان، نگرانی، خشم یا آشفتگی کاسته شدن و به حالت آرامش رسیدن.","To calm down or become peaceful after excitement, worry, anger, or agitation.","هدأَ أو أصبح هادئاً بعد انفعال أو قلق أو غضب أو اضطراب."],
 "مشاور املاک":["فرد یا کارشناس واسطه در خرید، فروش یا اجارهٔ خانه و ملک که به طرفین معامله راهنمایی می‌دهد.","A real-estate agent or property consultant who assists people with buying, selling, or renting property.","وسيط عقاري أو مستشار عقارات يساعد الأطراف في شراء العقارات أو بيعها أو استئجارها."],
 "اجاره‌نامه":["قرارداد کتبی میان صاحب‌خانه و مستأجر که شرایط، مدت و مبلغ اجارهٔ ملک را مشخص می‌کند.","A lease or rental agreement; a written contract specifying the terms, duration, and rent for a property.","عقد إيجار؛ اتفاق مكتوب يحدّد شروط ومدة وأجرة استئجار عقار بين المالك والمستأجر."],
 "اسباب‌کشی":["فرایند جمع کردن و انتقال وسایل خانه یا محل کار از یک مکان به مکان دیگر.","Moving house or relocation; the process of packing and transporting household or workplace belongings to another place.","نقل الأثاث أو الانتقال؛ عملية جمع أغراض المنزل أو العمل ونقلها من مكان إلى آخر."],
 "محلهٔ خلوت":["محله‌ای با رفت‌وآمد، جمعیت یا سروصدای کمتر که معمولاً آرام‌تر از مناطق شلوغ است.","A quiet neighbourhood with less traffic, fewer people, or less noise than busier areas.","حيّ هادئ تقلّ فيه حركة المرور أو أعداد الناس أو الضوضاء مقارنةً بالمناطق المزدحمة."],
 "مرکز شهر":["بخش مرکزی شهر که معمولاً محل تمرکز اداره‌ها، فروشگاه‌ها، خدمات و فعالیت‌های شهری است.","The city centre or downtown; the central area where offices, shops, services, and urban activities are concentrated.","وسط المدينة؛ المنطقة المركزية التي تتركّز فيها عادةً الدوائر والمتاجر والخدمات والأنشطة الحضرية."],
 "نورگیر":["پنجره یا بخشی از ساختمان که برای وارد کردن نور طبیعی به فضای داخلی ساخته شده است.","A skylight or light well; a window or architectural feature designed to bring natural light indoors.","منوّر أو فتحة إضاءة؛ نافذة أو جزء معماري صُمّم لإدخال الضوء الطبيعي إلى داخل المبنى."],
 "انباری":["فضای کوچک یا اتاقی برای نگهداری وسایل، ابزار و چیزهایی که هر روز استفاده نمی‌شوند.","A storage room or storeroom used to keep belongings, tools, and items not needed every day.","مخزن أو غرفة تخزين تُحفظ فيها الأغراض والأدوات والأشياء التي لا تُستعمل يومياً."],
 "کنتور مشترک":["دستگاه اندازه‌گیری مصرف آب، برق یا گاز که میزان مصرف چند واحد یا مشترک را به صورت مشترک ثبت می‌کند.","A shared utility meter that records the combined water, electricity, or gas consumption of multiple units or users.","عداد خدمات مشترك يسجّل إجمالي استهلاك الماء أو الكهرباء أو الغاز لعدة وحدات أو مشتركين."],
 "رفت‌وآمد":["آمدن و رفتن مکرر افراد یا وسایل نقلیه میان مکان‌ها؛ همچنین تردد روزانه.","Commuting or coming and going; the repeated movement of people or vehicles between places.","التردّد والتنقّل؛ حركة الأشخاص أو المركبات ذهاباً وإياباً بين الأماكن بصورة متكرّرة."],
 "سرمایه‌گذاری":["اختصاص دادن پول یا منابع به دارایی یا فعالیتی با هدف کسب سود یا منفعت در آینده.","Investment; committing money or resources to an asset or activity in expectation of future benefit or profit.","الاستثمار؛ تخصيص المال أو الموارد لأصل أو نشاط بهدف تحقيق منفعة أو ربح في المستقبل."],
 "هزینهٔ دادگاه":["مبلغی که برای رسیدگی قضایی، ثبت پرونده، خدمات حقوقی یا دیگر مراحل دادرسی پرداخت می‌شود.","Court costs or legal fees; money paid for filing a case, court proceedings, legal services, or other litigation expenses.","تكاليف المحكمة أو الرسوم القضائية؛ مبالغ تُدفع لتسجيل الدعوى أو إجراءات التقاضي أو الخدمات القانونية أو غيرها من نفقات المحاكمة."],
 "حمایت از مستأجر":["اقدام‌ها و قوانین برای حفظ حقوق مستأجر و جلوگیری از رفتار ناعادلانه یا بی‌ثباتی در اجارهٔ مسکن.","Tenant protection; laws and measures intended to safeguard renters' rights and prevent unfair treatment or housing instability.","حماية المستأجر؛ قوانين وإجراءات تهدف إلى صون حقوق المستأجرين ومنع المعاملة غير العادلة أو عدم استقرار السكن."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH16=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 17. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "داماد":["مردی که ازدواج می‌کند؛ همچنین شوهر دختر نسبت به پدر و مادر او.","A groom; a man who is getting married, or a son-in-law in relation to his wife's parents.","عريس؛ الرجل الذي يتزوّج، ويُقال أيضاً لزوج الابنة بالنسبة إلى والديها."],
 "ترجیح دادن":["یک گزینه را در مقایسه با گزینه‌های دیگر بهتر دانستن و آن را انتخاب کردن.","To prefer; to consider one option better than others and choose it.","فضّلَ؛ رأى خياراً أفضل من غيره واختاره."],
 "امضا کردن":["با نوشتن نام یا نشانهٔ شخصی، سند یا نوشته‌ای را تأیید و رسمی کردن.","To sign a document or writing by writing one's name or personal mark to confirm it.","وقّعَ وثيقة أو نصّاً بكتابة اسمه أو علامته الشخصية لتأكيده وإضفاء الصفة الرسمية عليه."],
 "جایگزین کردن":["چیزی یا کسی را به جای مورد قبلی قرار دادن تا وظیفه یا نقش آن را بر عهده بگیرد.","To replace something or someone with another that takes its place or performs its role.","استبدلَ شيئاً أو شخصاً بآخر ليحلّ محلّه ويؤدي وظيفته أو دوره."],
 "سرمایه‌گذاری کردن":["پول یا منابع را در فعالیت یا دارایی‌ای به کار انداختن تا در آینده سود یا منفعتی به دست آید.","To invest money or resources in an activity or asset in expectation of future profit or benefit.","استثمرَ المال أو الموارد في نشاط أو أصل أملاً في تحقيق ربح أو منفعة مستقبلاً."],
 "اطلاع دادن":["اطلاعات یا خبری را به شخص یا گروهی رساندن و آن‌ها را آگاه کردن.","To inform or notify someone by giving them information or news.","أبلغَ شخصاً أو جماعةً بمعلومات أو خبر وجعلهم على علم به."],
 "شریک":["فرد یا نهادی که در کاری، مالکیتی یا مسئولیتی با دیگری سهیم است.","A partner; a person or organisation that shares an activity, ownership, or responsibility with another.","شريك؛ شخص أو مؤسسة تشارك غيرها في عمل أو ملكية أو مسؤولية."],
 "فقر":["وضعیت نداشتن درآمد یا امکانات کافی برای تأمین نیازهای اساسی زندگی.","Poverty; the condition of lacking sufficient income or resources to meet basic needs.","الفقر؛ حالة عدم امتلاك دخل أو موارد كافية لتلبية الاحتياجات الأساسية للحياة."],
 "مخارج":["پول‌هایی که برای خرید، خدمات یا ادارهٔ زندگی و فعالیت‌ها پرداخت می‌شود.","Expenses or expenditures; money spent on goods, services, living costs, or activities.","النفقات أو المصروفات؛ الأموال التي تُدفع لشراء السلع أو الخدمات أو لتكاليف المعيشة والأنشطة."],
 "صدقه":["بخشش مال یا کمک به نیازمندان با نیت خیر و رضای خدا؛ در کاربرد دینی نوعی انفاق است.","Charity or alms; giving money or assistance to people in need as an act of kindness and devotion to God.","الصدقة؛ بذل المال أو المساعدة للمحتاجين بقصد الخير وابتغاء رضا الله."],
 "ثواب":["پاداش معنوی یا الهی برای انجام کار نیک و اطاعت از فرمان خدا.","Spiritual or divine reward for doing good deeds and obeying God's commands.","الثواب؛ الأجر المعنوي أو الإلهي على فعل الخير وطاعة أوامر الله."],
 "کارگاه":["مکانی برای انجام کارهای فنی، تولیدی، هنری یا آموزشی؛ همچنین جلسهٔ آموزشی عملی و گروهی.","A workshop; a place for practical, technical, artistic, or production work, or a hands-on group training session.","ورشة؛ مكان للأعمال الفنية أو الإنتاجية أو التدريبية، ويعني أيضاً جلسة تدريب عملي جماعية."],
 "وام":["مبلغی پول یا دارایی که به شخص داده می‌شود و او متعهد است در زمان یا شرایط مشخص آن را بازپرداخت کند.","A loan; money or property given to someone with an obligation to repay it under agreed conditions.","قرض؛ مبلغ من المال أو ممتلكات تُعطى لشخص مع التزامه بردّها في وقت أو شروط متفق عليها."],
 "پس‌انداز":["بخشی از درآمد یا پول که خرج نمی‌شود و برای نیازها یا هدف‌های آینده نگهداری می‌شود.","Savings; money from income that is not spent but kept for future needs or goals.","المدّخرات؛ جزء من الدخل أو المال لا يُنفق بل يُحتفظ به لحاجات أو أهداف مستقبلية."],
 "بدهکار":["کسی که به شخص یا نهادی پول یا تعهدی دارد و باید آن را پرداخت یا انجام دهد.","A debtor; someone who owes money or an obligation to another person or organisation.","مدين؛ شخص عليه مال أو التزام لشخص أو مؤسسة أخرى ويجب عليه سداده أو الوفاء به."],
 "یک‌پنجم":["یک قسمت از پنج قسمت مساوی یک کل؛ معادل بیست درصد آن.","One-fifth; one of five equal parts of a whole, equivalent to twenty percent.","الخُمس؛ جزء واحد من خمسة أجزاء متساوية من الكل، أي عشرون بالمئة."],
 "پول نقد":["پول به شکل اسکناس و سکه که برای پرداخت مستقیم استفاده می‌شود، نه انتقال بانکی یا اعتبار.","Cash; money in the form of banknotes and coins used for direct payment rather than bank transfer or credit.","النقد؛ المال على شكل أوراق نقدية وعملات معدنية يُستعمل للدفع المباشر لا للتحويل المصرفي أو الائتمان."],
 "بودجهٔ ماهانه":["برنامه‌ای برای برآورد و تقسیم درآمد و هزینه‌های یک ماه.","A monthly budget; a plan for estimating and allocating income and expenses over one month.","ميزانية شهرية؛ خطة لتقدير الدخل والنفقات وتوزيعهما خلال شهر واحد."],
 "وصیت":["سفارش یا دستور شخص دربارهٔ اموال، مسئولیت‌ها یا خواسته‌هایش برای اجرا پس از مرگ؛ همچنین توصیه‌ای مهم.","A will or testament; a person's instructions about property or wishes to be carried out after death; also an important piece of advice.","وصية؛ تعليمات الشخص بشأن أمواله أو رغباته لتنفيذها بعد وفاته، وتأتي أيضاً بمعنى نصيحة مهمة."],
 "نیاکان":["افراد نسل‌های پیشین یک خانواده یا قوم که نسل‌های بعد از آنان پدید آمده‌اند.","Ancestors or forebears; people from earlier generations of a family or community.","الأجداد والأسلاف؛ أشخاص من أجيال سابقة تنحدر منهم الأجيال اللاحقة في الأسرة أو الجماعة."],
 "گاوآهن":["ابزار کشاورزی برای شخم زدن و زیرورو کردن خاک زمین پیش از کاشت.","A plough; an agricultural tool used to cut and turn soil before planting.","محراث؛ أداة زراعية تُستعمل لحرث الأرض وتقليب تربتها قبل الزراعة."],
 "بیل":["ابزار دستی با تیغه‌ای پهن برای کندن، جابه‌جا کردن خاک، شن یا مواد دیگر.","A shovel or spade; a hand tool with a broad blade used for digging and moving soil, sand, or other material.","مجرفة؛ أداة يدوية ذات نصل عريض تُستعمل للحفر ونقل التراب أو الرمل أو مواد أخرى."],
 "محصول":["چیزی که از کشت، تولید یا فعالیتی به دست می‌آید؛ مانند محصول کشاورزی یا کالای تولیدشده.","A product or crop; something obtained through cultivation, manufacturing, or another activity.","منتج أو محصول؛ شيء ينتج عن الزراعة أو التصنيع أو نشاط آخر."],
 "ماه مهر":["هفتمین ماه تقویم هجری شمسی که آغاز آن معمولاً با شروع پاییز در ایران همراه است.","Mehr; the seventh month of the Solar Hijri calendar, beginning around the start of autumn in Iran.","مهر؛ الشهر السابع من التقويم الهجري الشمسي، ويبدأ عادةً مع بداية الخريف في إيران."],
 "واژهٔ مخفف":["واژه یا صورتی کوتاه‌شده که از حذف بخشی از یک عبارت یا نام ساخته می‌شود.","An abbreviated word or shortened form created by omitting part of a phrase or name.","كلمة مختصرة أو صيغة موجزة تتكوّن بحذف جزء من عبارة أو اسم."],
 "قرض دادن":["پول یا چیزی را به دیگری سپردن با این توافق که در آینده بازگردانده شود.","To lend; to give money or an item to someone on the understanding that it will be returned.","أقرضَ؛ أعطى مالاً أو شيئاً لشخص على أن يعيده لاحقاً."],
 "شریک شدن":["با فرد یا گروهی در مالکیت، فعالیت، هزینه یا مسئولیتی سهیم شدن.","To become a partner or share ownership, activity, costs, or responsibility with another person or group.","شاركَ؛ أصبح شريكاً مع شخص أو جماعة في ملكية أو نشاط أو نفقات أو مسؤولية."],
 "به ارث رسیدن":["پس از درگذشت صاحب مال، دارایی یا حقی طبق قانون یا وصیت به فرد دیگری منتقل شدن.","To be inherited; for property or a right to pass to another person after its owner's death under law or a will.","وُرثَ؛ انتقلَ مال أو حقّ إلى شخص آخر بعد وفاة مالكه بموجب القانون أو الوصية."],
 "به ارث گذاشتن":["دارایی یا حقی را به گونه‌ای باقی گذاشتن که پس از مرگ به وارثان منتقل شود.","To bequeath or leave property or a right to heirs to receive after one's death.","أوصى بمال أو حقّ وتركه لينتقل إلى الورثة بعد وفاته."],
 "زیاده‌خواهی کردن":["بیش از نیاز یا حق خود خواستن و به سهم یا امکانات موجود قانع نبودن.","To be greedy or demand more than one's needs or fair share.","طمعَ وطلبَ أكثر من حاجته أو من نصيبه العادل ولم يقنع بما لديه."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH17=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 18. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "اینترنت‌بانک":["خدمات بانکی که مشتری از طریق اینترنت و وب‌سایت یا برنامهٔ بانک، بدون مراجعهٔ حضوری انجام می‌دهد.","Internet banking; banking services a customer uses through a bank's website or app without visiting a branch.","الخدمات المصرفية عبر الإنترنت؛ خدمات ينجزها العميل من خلال موقع البنك أو تطبيقه من دون زيارة الفرع."],
 "کارت‌خوان":["دستگاهی که اطلاعات کارت بانکی را می‌خواند و پرداخت یا تراکنش الکترونیکی را انجام می‌دهد.","A card reader or payment terminal that reads a bank card and processes an electronic payment or transaction.","جهاز قراءة البطاقات أو نقطة البيع؛ يقرأ البطاقة المصرفية وينفّذ عملية دفع أو معاملة إلكترونية."],
 "قبض":["سند یا برگه‌ای که مبلغ قابل پرداخت برای خدماتی مانند آب، برق، گاز یا تلفن را نشان می‌دهد؛ همچنین رسید دریافت پول.","A bill or invoice showing an amount due for services such as water, electricity, gas, or telephone; also a receipt.","فاتورة أو مستند يبيّن المبلغ المستحق لخدمات مثل الماء والكهرباء والغاز والهاتف؛ ويعني أيضاً إيصال قبض المال."],
 "شماره حساب":["شناسهٔ عددی یا ترکیبی که بانک برای تشخیص حساب بانکی هر مشتری اختصاص می‌دهد.","An account number; a numeric or alphanumeric identifier assigned by a bank to a customer's account.","رقم الحساب؛ معرّف رقمي أو مكوّن من أرقام وحروف يخصّصه البنك لحساب العميل."],
 "شماره کارت":["شمارهٔ درج‌شده روی کارت بانکی که برای شناسایی کارت در تراکنش‌ها به کار می‌رود.","A card number; the number printed on a bank card and used to identify it in transactions.","رقم البطاقة؛ الرقم المدوّن على البطاقة المصرفية ويُستعمل للتعرّف إليها في المعاملات."],
 "دفترچه حساب":["دفتر یا سند بانکی که اطلاعات حساب و تراکنش‌های آن را ثبت یا نمایش می‌دهد.","A bank passbook or account booklet that records or displays account information and transactions.","دفتر الحساب المصرفي؛ كتيّب أو وثيقة مصرفية تسجّل بيانات الحساب ومعاملاته أو تعرضها."],
 "سود بانکی":["مبلغ یا درصدی که بانک در برابر سپرده یا وام، طبق قرارداد و مقررات مالی محاسبه می‌کند.","Bank interest; an amount or rate calculated by a bank on a deposit or loan under the applicable agreement and rules.","الفائدة المصرفية؛ مبلغ أو نسبة يحسبها البنك على وديعة أو قرض وفق الاتفاق والأنظمة المالية."],
 "چک":["سند مالی مکتوبی که صاحب حساب با آن به بانک دستور می‌دهد مبلغی را به دارنده یا شخص مشخص بپردازد.","A cheque or check; a written financial order instructing a bank to pay a specified amount to a named person or bearer.","شيك؛ وثيقة مالية مكتوبة يأمر بها صاحب الحساب البنك بدفع مبلغ محدّد لحاملها أو لشخص معيّن."],
 "چک برگشتی":["چکی که بانک به دلیل کافی نبودن موجودی یا وجود مانع قانونی یا اداری آن را پرداخت نمی‌کند.","A bounced cheque; a cheque the bank refuses to pay because of insufficient funds or another legal or administrative restriction.","شيك مرتجع؛ شيك يرفض البنك صرفه لعدم كفاية الرصيد أو لوجود مانع قانوني أو إداري."],
 "سکه":["قطعه‌ای فلزی با شکل و وزن مشخص که به عنوان پول یا برای یادبود و سرمایه‌گذاری ضرب می‌شود.","A coin; a shaped metal piece issued as money or minted for commemorative or investment purposes.","عملة معدنية؛ قطعة من المعدن ذات شكل ووزن محدّد تُسكّ كنقود أو للتذكار والاستثمار."],
 "نقره":["فلزی گران‌بها، سفید و براق که در ساخت زیورآلات، ظروف و برخی تجهیزات به کار می‌رود.","Silver; a precious, shiny white metal used in jewellery, tableware, and some equipment.","الفضة؛ معدن نفيس أبيض لامع يُستعمل في صناعة الحلي والأواني وبعض المعدات."],
 "بانک مرکزی":["نهاد اصلی پولی یک کشور که سیاست پولی، انتشار پول و نظارت بر نظام بانکی را بر عهده دارد.","A central bank; a country's main monetary authority responsible for monetary policy, currency issuance, and oversight of the banking system.","البنك المركزي؛ السلطة النقدية الرئيسية في الدولة والمسؤولة عن السياسة النقدية وإصدار العملة والإشراف على النظام المصرفي."],
 "شعبه":["یکی از واحدها یا دفترهای محلی یک بانک، اداره یا سازمان که خدمات آن مجموعه را ارائه می‌کند.","A branch; a local office or unit of a bank, government department, or organisation that provides its services.","فرع؛ مكتب أو وحدة محلية لبنك أو دائرة أو مؤسسة تقدّم خدمات الجهة."],
 "مدارک شناسایی":["اسناد رسمی مانند شناسنامه یا کارت ملی که برای تأیید هویت فرد استفاده می‌شوند.","Identity documents; official records such as a birth certificate or national ID card used to verify a person's identity.","وثائق إثبات الهوية؛ مستندات رسمية مثل شهادة الميلاد أو بطاقة الهوية الوطنية للتحقّق من هوية الشخص."],
 "رمز عبور":["رشته‌ای محرمانه از حروف، اعداد یا نشانه‌ها که برای ورود به حساب یا سامانه استفاده می‌شود.","A password; a confidential sequence of letters, numbers, or symbols used to access an account or system.","كلمة مرور؛ سلسلة سرية من الحروف أو الأرقام أو الرموز تُستعمل للدخول إلى حساب أو نظام."],
 "افتتاح کردن":["کار، فعالیت یا مکانی را به طور رسمی آغاز کردن؛ مانند افتتاح حساب بانکی یا ساختمان.","To open or inaugurate something officially, such as a bank account, business, or building.","افتتحَ شيئاً رسمياً، مثل حساب مصرفي أو مشروع أو مبنى."],
 "فعال کردن":["وسیله، حساب یا خدمتی را از حالت غیرفعال خارج کردن و قابل استفاده ساختن.","To activate or enable a device, account, or service so that it can be used.","فعّلَ جهازاً أو حساباً أو خدمة وأخرجه من حالة التعطيل ليصبح قابلاً للاستعمال."],
 "سود گرفتن":["در برابر سپرده‌گذاری، وام یا فعالیت اقتصادی، سود مالی دریافت کردن.","To receive interest or profit from a deposit, loan, or financial activity.","حصلَ على فائدة أو ربح من وديعة أو قرض أو نشاط مالي."],
 "سود دادن":["برای سپرده یا سرمایه، سود مالی پرداخت کردن یا بازده ایجاد کردن.","To pay interest or yield a financial return on a deposit or investment.","دفعَ فائدة مالية أو حقّق عائداً على وديعة أو استثمار."],
 "سوزاندن کارت":["کارت را با آتش یا حرارت از بین بردن؛ در برخی بافت‌ها ممکن است به باطل یا غیرفعال کردن کارت اشاره کند.","To burn a card physically; in some contexts, the phrase may refer to cancelling or deactivating a card.","أحرقَ البطاقة بالنار أو الحرارة؛ وقد يُقصد في بعض السياقات إبطال البطاقة أو تعطيلها."],
 "حاجت":["نیاز یا خواسته‌ای که شخص امیدوار است برآورده شود؛ در کاربرد دینی، خواسته‌ای که برای آن دعا می‌شود.","A need or wish that someone hopes will be fulfilled; in religious use, a request presented in prayer.","حاجة أو أمنية يرجو الشخص قضاءها؛ وفي الاستعمال الديني طلب يدعو الإنسان بتحقيقه."],
 "لیلة الرغائب":["شبی در آغاز ماه رجب که در برخی سنت‌های اسلامی، به‌ویژه در میان شیعیان، با دعا و اعمال عبادی ویژه گرامی داشته می‌شود.","Laylat al-Raghaib, the Night of Wishes; a night at the beginning of Rajab observed in some Islamic traditions, especially among Shi'a, with special prayers and devotional acts.","ليلة الرغائب؛ ليلة في بداية شهر رجب تُحيى في بعض التقاليد الإسلامية، ولا سيّما عند الشيعة، بالدعاء وأعمال عباديّة خاصة."],
 "باغبان":["کسی که از باغ و گیاهان آن مراقبت می‌کند و به کاشت، هرس و نگهداری آن‌ها می‌پردازد.","A gardener; someone who cares for a garden and plants by cultivating, pruning, and maintaining them.","بستاني؛ شخص يعتني بالبستان ونباتاته من خلال الزراعة والتقليم والصيانة."],
 "آرزوی ناپسند":["خواسته‌ای که از نظر اخلاقی یا دینی نادرست و زیان‌آور دانسته می‌شود.","An undesirable or improper wish; a desire considered morally or religiously wrong or harmful.","أمنية مذمومة؛ رغبة تُعدّ خاطئة أو ضارة من الناحية الأخلاقية أو الدينية."],
 "تلاش و کوشش":["به‌کارگیری نیرو، زمان و پشتکار برای رسیدن به هدف یا انجام کاری دشوار.","Effort and endeavour; using energy, time, and perseverance to achieve a goal or complete a difficult task.","السعي والجهد؛ بذل الطاقة والوقت والمثابرة لتحقيق هدف أو إنجاز عمل صعب."],
 "یار":["دوست، همراه یا پشتیبان؛ کسی که در مسیر یا کاری به دیگری کمک می‌کند.","A friend, companion, or supporter; someone who accompanies or helps another person.","صديق أو رفيق أو نصير؛ شخص يرافق غيره أو يساعده في طريق أو عمل."],
 "مضارع التزامی":["یکی از ساخت‌های فعل در دستور زبان فارسی که معمولاً برای بیان خواسته، احتمال، ضرورت یا هدف در زمان حال و آینده به کار می‌رود.","The Persian present subjunctive; a verb form commonly used to express wishes, possibility, necessity, or purpose in present and future contexts.","المضارع الالتزامي في الفارسية؛ صيغة فعل تُستعمل غالباً للتعبير عن الرغبة أو الاحتمال أو الضرورة أو الغاية في الحاضر والمستقبل."],
 "ماضی التزامی":["ساختی فعلی در دستور زبان فارسی که معمولاً با «بوده باشم» یا شکل‌های مشابه ساخته می‌شود و برای بیان احتمال یا فرض دربارهٔ گذشته به کار می‌رود.","The Persian past subjunctive; a verb construction often formed with a past participle and a form of 'to be', used for possibility or supposition about the past.","الماضي الالتزامي في الفارسية؛ تركيب فعلي يُبنى غالباً باسم المفعول مع صيغة من فعل الكينونة، ويُستعمل للاحتمال أو الافتراض المتعلّق بالماضي."],
 "جملهٔ آرزویی":["جمله‌ای که خواسته، آرزو یا امید گوینده را دربارهٔ رخ دادن چیزی بیان می‌کند.","A wish sentence; a sentence that expresses the speaker's wish, hope, or desire for something to happen.","جملة تمنٍّ؛ جملة تعبّر عن رغبة المتكلّم أو أمله في حدوث أمر ما."],
 "بزرگراه":["راهی عریض و پرظرفیت برای حرکت سریع خودروها که معمولاً دسترسی‌های کنترل‌شده و تقاطع‌های محدود دارد.","A highway or expressway; a wide, high-capacity road designed for faster vehicle travel, usually with controlled access and limited intersections.","طريق سريع أو طريق رئيسي واسع وعالي السعة مخصّص لحركة المركبات بسرعة، مع مداخل منظّمة وتقاطعّات محدودة عادةً."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH18=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 19. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "سرعت غیرمجاز":["سرعتی که از حد تعیین‌شده در قانون یا تابلوهای راهنمایی و رانندگی بیشتر باشد.","An unlawful speed; a speed exceeding the limit set by law or traffic signs.","سرعة مخالفة؛ سرعة تتجاوز الحدّ المحدّد في القانون أو إشارات المرور."],
 "تردد":["رفت‌وآمد و حرکت مکرر افراد یا وسایل نقلیه در یک مسیر یا میان مکان‌ها.","Traffic or movement; the repeated passage of people or vehicles along a route or between places.","التردّد أو حركة المرور؛ تنقّل الأشخاص أو المركبات بصورة متكرّرة على طريق أو بين أماكن."],
 "آرزو کردن":["خواستن یا امید داشتن به اینکه چیزی در آینده رخ دهد یا به دست آید.","To wish or hope that something will happen or be achieved in the future.","تمنّى؛ رغبَ أو أملَ في حدوث شيء أو تحقيقه في المستقبل."],
 "امیدوار بودن":["باور یا انتظار مثبت داشتن که اتفاق خوبی رخ دهد یا هدفی تحقق پیدا کند.","To be hopeful; to have a positive expectation that something good will happen or a goal will be achieved.","كان متفائلاً أو راجياً؛ توقّع بإيجابية حدوث أمر طيّب أو تحقيق هدف."],
 "تلاش کردن":["برای انجام کاری یا رسیدن به هدفی با صرف نیرو و پشتکار کوشش کردن.","To try or make an effort to do something or achieve a goal.","حاولَ أو بذلَ جهداً لإنجاز عمل أو بلوغ هدف."],
 "خوب شدن":["از وضعیت نامطلوب به حالت بهتر رسیدن؛ دربارهٔ بیمار یعنی بهبود یافتن.","To get better or improve; when referring to an ill person, to recover.","تحسّنَ أو شُفيَ؛ ويقال عن المريض بمعنى تعافى."],
 "مشورت":["گفت‌وگو با فرد آگاه یا مورد اعتماد برای شنیدن نظر و راهنمایی پیش از تصمیم‌گیری.","Consultation; discussing a matter with a knowledgeable or trusted person to obtain advice before deciding.","استشارة؛ التشاور مع شخص خبير أو موثوق للحصول على رأيه ونصيحته قبل اتخاذ القرار."],
 "مقصر":["کسی که مسئول اشتباه، کوتاهی یا رخ دادن یک مشکل شناخته می‌شود.","The person at fault or responsible for a mistake, failure, or problem.","المقصّر أو المسؤول؛ الشخص الذي يُعدّ مسؤولاً عن خطأ أو إهمال أو مشكلة."],
 "ناامیدی":["از دست دادن امید یا انتظار مثبت نسبت به آینده یا نتیجهٔ یک کار.","Hopelessness or despair; the loss of hope or positive expectation about the future or an outcome.","اليأس؛ فقدان الأمل أو التوقّع الإيجابي تجاه المستقبل أو نتيجة أمر ما."],
 "سرطان":["گروهی از بیماری‌ها که در آن سلول‌های غیرطبیعی به شکل کنترل‌نشده رشد می‌کنند و ممکن است به بافت‌های دیگر گسترش یابند.","Cancer; a group of diseases in which abnormal cells grow uncontrollably and may spread to other tissues.","السرطان؛ مجموعة أمراض تنمو فيها خلايا غير طبيعية بصورة غير منضبطة وقد تنتشر إلى أنسجة أخرى."],
 "ریه":["یکی از دو اندام اصلی دستگاه تنفس که اکسیژن را وارد خون می‌کند و دی‌اکسید کربن را از آن خارج می‌سازد.","A lung; one of the two main respiratory organs that transfers oxygen into the blood and removes carbon dioxide.","الرئة؛ أحد العضوين الرئيسيين في الجهاز التنفسي، ينقل الأكسجين إلى الدم ويطرح منه ثاني أكسيد الكربون."],
 "سیگار":["محصولی معمولاً استوانه‌ای از توتون پیچیده‌شده در کاغذ که با روشن کردن آن دود استنشاق می‌شود.","A cigarette; a small cylinder of tobacco wrapped in paper that is lit and smoked.","سيجارة؛ لفافة صغيرة من التبغ ملفوفة بالورق تُشعل ويُستنشق دخانها."],
 "حسابی":["به مقدار زیاد یا به شکل کامل و درست؛ در زبان محاوره برای تأکید بر شدت یا میزان چیزی.","Thoroughly, properly, or considerably; colloquially used to emphasise the degree or amount of something.","بكثرة أو بصورة تامة وصحيحة؛ وتُستعمل عاميّاً للتأكيد على شدّة الشيء أو مقداره."],
 "بمب اتم":["سلاح هسته‌ای که انرژی بسیار زیادی را از واکنش‌های هسته‌ای آزاد می‌کند و می‌تواند ویرانی گسترده ایجاد کند.","An atomic bomb; a nuclear weapon that releases enormous energy through nuclear reactions and can cause widespread destruction.","قنبلة ذرية؛ سلاح نووي يطلق طاقة هائلة عبر تفاعلات نووية ويمكن أن يسبّب دماراً واسعاً."],
 "سلاح":["وسیله یا ابزاری که برای حمله، دفاع یا وارد کردن آسیب به کار می‌رود.","A weapon; an instrument or device used for attack, defence, or causing harm.","سلاح؛ أداة أو وسيلة تُستخدم للهجوم أو الدفاع أو إلحاق الضرر."],
 "پیشروی":["حرکت رو به جلو یا گسترش یافتن در یک مسیر، فعالیت یا عملیات؛ در زمینهٔ نظامی به جلو رفتن نیروها.","Advance or progress; moving forward or expanding in a course of action, including the movement of military forces.","تقدّم أو توغّل؛ الحركة إلى الأمام أو التوسّع في مسار أو نشاط أو عملية، ومنها تقدّم القوات العسكرية."],
 "دفاع":["اقدام برای محافظت از خود، دیگران یا یک سرزمین در برابر حمله، خطر یا اتهام.","Defence; the act of protecting oneself, others, or a territory against attack, danger, or accusation.","الدفاع؛ القيام بحماية النفس أو الآخرين أو أرض من هجوم أو خطر أو اتهام."],
 "ارتش":["سازمان نظامی رسمی یک کشور که برای دفاع و انجام مأموریت‌های نظامی تشکیل شده است.","An army or armed forces; a country's official military organisation established for defence and military missions.","الجيش أو القوات المسلحة؛ المؤسسة العسكرية الرسمية للدولة التي تُنشأ للدفاع وتنفيذ المهام العسكرية."],
 "گروه تروریستی":["سازمانی که برای ایجاد ترس عمومی یا دستیابی به هدف سیاسی یا ایدئولوژیک، از خشونت علیه غیرنظامیان یا تهدید آن استفاده می‌کند.","A terrorist group; an organisation that uses or threatens violence against civilians to spread fear or pursue political or ideological aims.","جماعة إرهابية؛ تنظيم يستخدم العنف ضد المدنيين أو يهدّد به لنشر الخوف أو تحقيق أهداف سياسية أو أيديولوجية."],
 "رایانامه":["پیام یا نامه‌ای که از طریق شبکهٔ اینترنت به نشانی الکترونیکی شخص دیگری فرستاده می‌شود؛ ایمیل.","Email or electronic mail; a message sent over the internet to another person's electronic address.","البريد الإلكتروني؛ رسالة تُرسل عبر الإنترنت إلى العنوان الإلكتروني لشخص آخر."],
 "درمانگاه":["مرکز بهداشتی یا پزشکی برای معاینه، مشاوره و درمان بیماران که معمولاً خدمات بستری گسترده ندارد.","A clinic or outpatient medical centre where patients receive examinations, advice, and treatment, usually without extensive inpatient services.","عيادة أو مركز طبي للمعاينة والاستشارة والعلاج، ولا يوفّر عادةً خدمات تنويم واسعة."],
 "پایانه":["محل آغاز یا پایان مسیر وسایل نقلیه و جابه‌جایی مسافران یا بار؛ مانند پایانهٔ اتوبوس یا باربری.","A terminal or station where a transport route begins or ends and passengers or freight are handled.","محطّة نهائية أو مرفق يبدأ منه مسار النقل أو ينتهي، وتُخدم فيه حركة الركاب أو البضائع."],
 "کالابرگ":["برگه یا اعتبار اختصاص‌یافته برای خرید کالاهای مشخص و ضروری؛ در ایران به طرح‌های حمایتی خرید کالا نیز گفته می‌شود.","A goods voucher or food subsidy credit used to purchase specified essential items; in Iran, it can refer to government-supported shopping schemes.","قسيمة سلع أو رصيد دعم يُخصّص لشراء مواد أساسية محدّدة؛ ويُستعمل في إيران أيضاً لبرامج الدعم الحكومي للشراء."],
 "پاراگراف":["بخشی از یک نوشته که چند جملهٔ مرتبط دربارهٔ یک موضوع یا ایده را در بر می‌گیرد و معمولاً با سطر تازه مشخص می‌شود.","A paragraph; a section of writing containing related sentences about one topic or idea, usually marked by a new line.","فقرة؛ جزء من نصّ يضمّ جملاً مترابطة حول موضوع أو فكرة واحدة، ويُميّز عادةً بسطر جديد."],
 "کلینیک":["مرکز ارائهٔ خدمات پزشکی برای تشخیص، مشاوره و درمان؛ ممکن است در یک تخصص خاص فعالیت کند.","A clinic; a healthcare facility providing diagnosis, consultation, and treatment, sometimes specialising in one field.","عيادة؛ منشأة صحية تقدّم التشخيص والاستشارة والعلاج، وقد تتخصّص في مجال معيّن."],
 "برنامه‌نویسی":["فرایند نوشتن و سازمان‌دهی دستورها در یک زبان برنامه‌نویسی برای ساخت نرم‌افزار یا کنترل رایانه.","Programming; the process of writing and organising instructions in a programming language to create software or control a computer.","البرمجة؛ عملية كتابة التعليمات وتنظيمها بلغة برمجية لإنشاء برنامج أو التحكّم بالحاسوب."],
 "پشیمان شدن":["پس از انجام کاری یا گرفتن تصمیمی احساس تأسف کردن و آرزو داشتن که آن کار به شکل دیگری انجام می‌شد.","To regret; to feel sorry about an action or decision and wish it had been different.","ندمَ؛ شعر بالأسف على فعل أو قرار وتمنّى لو كان قد تصرّف بطريقة أخرى."],
 "وقت گذاشتن":["برای انجام کاری، شخصی یا هدفی زمان اختصاص دادن و آن را صرف کردن.","To devote or spend time on a task, person, or goal.","خصّصَ وقتاً لعمل أو لشخص أو لهدف وأنفقه عليه."],
 "پردرآمد":["دارای درآمد زیاد؛ دربارهٔ شغل یا فعالیتی که پول زیادی به دست می‌آورد نیز گفته می‌شود.","High-income or lucrative; earning or providing a relatively large amount of money.","مرتفع الدخل أو مُربح؛ يحقّق أو يوفّر مقداراً كبيراً نسبياً من المال."],
 "شرکت خصوصی":["شرکتی که مالکیت و ادارهٔ آن در اختیار افراد یا سرمایه‌گذاران غیردولتی است، نه دولت.","A private company; a business owned and operated by individuals or non-government investors rather than the state.","شركة خاصة؛ مؤسسة تجارية يملكها ويديرها أفراد أو مستثمرون غير حكوميين، لا الدولة."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH19=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 20. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "تخفیف":["کاهش بخشی از قیمت کالا یا خدمات نسبت به قیمت معمول یا اولیه.","A discount or reduction in the usual or original price of a product or service.","خصم أو تخفيض؛ إنقاص جزء من السعر المعتاد أو الأصلي لسلعة أو خدمة."],
 "حراجی":["محل یا رویدادی برای فروش کالا، معمولاً با قیمت پایین‌تر یا از راه مزایده.","A sale or auction event where goods are sold, often at reduced prices or through competitive bidding.","بيع أو مزاد؛ مكان أو مناسبة تُباع فيها السلع غالباً بأسعار مخفّضة أو بالمزايدة."],
 "هزینهٔ غیرضروری":["خرجی که برای نیازهای اساسی یا هدف مهمی لازم نیست و می‌توان از آن صرف‌نظر کرد.","An unnecessary expense; spending that is not required for essential needs or an important goal.","نفقة غير ضرورية؛ مبلغ يُنفق على أمر لا يلزم للحاجات الأساسية أو لهدف مهم ويمكن الاستغناء عنه."],
 "هدف واقعی":["مقصود اصلی و حقیقی یک کار یا برنامه، نه هدف ظاهری یا اعلام‌شدهٔ آن.","The real or underlying goal of an action or plan, rather than its apparent or stated objective.","الهدف الحقيقي أو الأساسي لعمل أو خطة، لا الهدف الظاهري أو المعلن."],
 "ارزیابی":["بررسی و سنجش ارزش، کیفیت، عملکرد یا میزان موفقیت چیزی بر اساس معیارهای مشخص.","Evaluation or assessment; examining the value, quality, performance, or success of something using defined criteria.","التقييم؛ فحص قيمة شيء أو جودته أو أدائه أو مدى نجاحه وفق معايير محدّدة."],
 "توانمندی":["داشتن دانش، مهارت یا قدرت لازم برای انجام کاری یا رسیدن به هدفی.","Capability or competence; having the knowledge, skill, or ability needed to perform a task or achieve a goal.","القدرة أو الكفاءة؛ امتلاك المعرفة أو المهارة أو القوة اللازمة لأداء عمل أو تحقيق هدف."],
 "سالنامه":["کتاب یا نشریه‌ای که اطلاعات، رویدادها، آمار یا یادداشت‌های مربوط به یک سال را گردآوری می‌کند.","An annual or yearbook; a book or publication collecting information, events, statistics, or notes for a year.","حولية أو كتاب سنوي؛ مطبوعة تجمع معلومات أو أحداثاً أو إحصاءات أو ملاحظات تخصّ سنة."],
 "تمرکز":["جمع کردن توجه ذهن بر یک موضوع یا کار و دور نگه داشتن آن از عوامل مزاحم.","Concentration or focus; directing one's attention to a subject or task while limiting distractions.","التركيز؛ توجيه الانتباه الذهني إلى موضوع أو عمل مع إبعاد المشتّتات."],
 "پرسش‌سازی":["فرایند ساختن و تنظیم پرسش‌های روشن و هدفمند برای بررسی یک موضوع یا به دست آوردن اطلاعات.","Question formulation; the process of creating and structuring clear, purposeful questions to investigate a topic or obtain information.","صياغة الأسئلة؛ عملية إنشاء أسئلة واضحة وهادفة وتنظيمها لدراسة موضوع أو الحصول على معلومات."],
 "حرف مشدد":["حرفی که در نوشتار عربی با نشانهٔ تشدید مشخص می‌شود و در تلفظ به صورت حرفی دوگانه یا کشیده ادا می‌شود.","A doubled or geminated Arabic consonant marked with shadda, pronounced as a strengthened or doubled consonant.","حرف مشدّد في الكتابة العربية تُوضع عليه علامة الشدّة ويُنطق كحرف مضاعف أو مشدّد."],
 "توسعه دادن":["چیزی را از نظر اندازه، دامنه، امکانات یا کیفیت گسترش دادن و به سطح بالاتری رساندن.","To develop or expand something in size, scope, capacity, or quality.","طوّرَ أو وسّعَ شيئاً من حيث الحجم أو النطاق أو الإمكانات أو الجودة."],
 "تمرکز کردن":["توجه و توان ذهنی خود را بر یک موضوع یا فعالیت مشخص متمرکز کردن.","To concentrate or focus one's attention and mental effort on a particular subject or activity.","ركّزَ انتباهه وجهده الذهني على موضوع أو نشاط محدّد."],
 "اولویت‌بندی کردن":["کارها یا گزینه‌ها را بر اساس اهمیت و فوریت مرتب کردن تا مشخص شود کدام‌یک زودتر انجام شود.","To prioritise tasks or options according to importance and urgency so that the order of action is clear.","رتّبَ الأولويات؛ نظّم الأعمال أو الخيارات بحسب الأهمية والاستعجال لتحديد ما ينبغي إنجازه أولاً."],
 "بدقول":["کسی که به وعده یا زمان توافق‌شده پایبند نمی‌ماند و معمولاً به قول خود عمل نمی‌کند.","Unreliable or someone who breaks promises; a person who does not keep agreed commitments or arrive on time.","مُخلّ بالوعد؛ شخص لا يلتزم بوعوده أو بالمواعيد المتفق عليها."],
 "خوش‌قول":["کسی که به وعده‌ها و زمان‌های تعیین‌شده پایبند است و به قول خود عمل می‌کند.","Reliable and true to one's word; someone who keeps promises and honours agreed times.","وفيّ بوعده؛ شخص يلتزم بوعوده ويحترم المواعيد المتفق عليها."],
 "بی‌ملاحظه":["کسی که هنگام رفتار یا سخن گفتن، احساسات، حقوق یا شرایط دیگران را در نظر نمی‌گیرد.","Inconsiderate; failing to take other people's feelings, rights, or circumstances into account.","غير مُراعٍ للآخرين؛ لا يأخذ مشاعر الناس أو حقوقهم أو ظروفهم في الحسبان."],
 "لجباز":["کسی که با وجود دلیل یا درخواست دیگران، سرسختانه بر نظر یا رفتار خود پافشاری می‌کند.","Stubborn; someone who insists on their own opinion or behaviour despite reasons or requests from others.","عنيد؛ شخص يصرّ على رأيه أو سلوكه رغم حجج الآخرين أو طلباتهم."],
 "رازدار":["کسی که رازهای دیگران را حفظ می‌کند و آن‌ها را بدون اجازه فاش نمی‌سازد.","Discreet or trustworthy with secrets; someone who keeps other people's confidences.","كتوم وحافظ للأسرار؛ شخص يصون أسرار الآخرين ولا يفشيها من دون إذن."],
 "پرحرف":["کسی که زیاد صحبت می‌کند و معمولاً سخنان طولانی یا فراوان دارد.","Talkative or loquacious; someone who speaks a great deal.","ثرثار أو كثير الكلام؛ شخص يتحدّث كثيراً وبإسهاب."],
 "شلخته":["نامرتب و بی‌نظم در ظاهر، لباس، وسایل یا انجام کارها.","Messy or untidy in appearance, clothing, belongings, or work habits.","فوضوي أو غير مرتب في المظهر أو الملابس أو الأغراض أو أداء الأعمال."],
 "صبور":["کسی که در برابر دشواری، تأخیر یا رفتار ناخوشایند دیگران شکیبایی نشان می‌دهد.","Patient; able to remain calm and endure difficulty, delay, or others' unpleasant behaviour.","صبور؛ من يتحلّى بالأناة ويتحمّل الصعوبات أو التأخير أو سلوك الآخرين المزعج."],
 "سلامت روان":["وضعیت بهزیستی روانی و عاطفی که به فرد کمک می‌کند با فشارهای زندگی کنار بیاید و در فعالیت‌های روزانه عملکرد مناسبی داشته باشد.","Mental health; a state of psychological and emotional well-being that helps a person cope with life's stresses and function in daily activities.","الصحة النفسية؛ حالة من العافية النفسية والعاطفية تساعد الشخص على التعامل مع ضغوط الحياة وأداء أنشطته اليومية."],
 "فشار خون":["نیرویی که خون هنگام جریان یافتن به دیوارهٔ رگ‌ها وارد می‌کند و معمولاً با دو عدد اندازه‌گیری می‌شود.","Blood pressure; the force exerted by circulating blood against the walls of blood vessels, usually measured with two numbers.","ضغط الدم؛ القوة التي يؤثّر بها الدم الجاري على جدران الأوعية الدموية، ويُقاس عادةً برقمين."],
 "بیماری قلبی":["هر بیماری یا اختلالی که ساختار یا عملکرد قلب را تحت تأثیر قرار دهد.","Heart disease; any condition or disorder that affects the structure or function of the heart.","مرض قلبي؛ أي حالة أو اضطراب يؤثّر في بنية القلب أو وظيفته."],
 "قول دادن":["به کسی وعده دادن که کاری را انجام می‌دهیم یا از انجام کاری خودداری می‌کنیم.","To promise someone that one will do something or refrain from doing something.","وعدَ شخصاً بأن يفعل شيئاً أو يمتنع عن فعله."],
 "جیغ کشیدن":["با صدای بسیار بلند و زیر، معمولاً از ترس، درد، هیجان یا خشم فریاد زدن.","To scream or shriek loudly, usually because of fear, pain, excitement, or anger.","صرخَ أو أطلقَ صرخة حادّة وعالية، غالباً بسبب الخوف أو الألم أو الحماس أو الغضب."],
 "غیررسمی":["بدون تشریفات یا قالب رسمی؛ صمیمی و متناسب با موقعیت‌های دوستانه یا روزمره.","Informal; without official formality or ceremony, suitable for casual or friendly situations.","غير رسمي؛ من دون طابع أو إجراءات رسمية، ومناسب للمواقف اليومية أو الودّية."],
 "رسمی":["مطابق مقررات، تشریفات یا قالب پذیرفته‌شدهٔ یک سازمان یا موقعیت رسمی.","Formal or official; following the accepted rules, procedures, or conventions of an organisation or official setting.","رسمي؛ مطابق للقواعد أو الإجراءات أو الأعراف المعتمدة في مؤسسة أو مناسبة رسمية."],
 "تقاضا":["درخواست یا خواسته‌ای که از شخص یا نهادی مطرح می‌شود؛ همچنین میزان خواست بازار برای کالا یا خدمات.","A request or demand made to a person or organisation; also, market demand for goods or services.","طلب أو تقاضٍ يوجّه إلى شخص أو مؤسسة؛ ويعني أيضاً حجم طلب السوق على السلع أو الخدمات."],
 "تسلیت":["ابراز همدردی با کسی که عزیزی را از دست داده یا دچار مصیبت شده است.","Condolences; an expression of sympathy to someone who has lost a loved one or suffered a bereavement.","التعزية؛ إظهار المواساة لشخص فقد عزيزاً أو أصابته مصيبة."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH20=Object.keys(rows);
})();
